			text = { L["Saphiron"], "", L["- Frostaura: dauerhafter Frostschaden -> Frostwiderstand für alle."], L["- Lebensentzug: Fluch auf Spielern -> sofort entfluchen."], L["- Flugphase: Eisblitz friert Spieler zu Eisblöcken -> danach hinter einem Eisblock vor Frostatem verstecken."], L["- Blizzard: wandernde Frostzonen -> ausweichen."], "", L["Taktik: Frostwiderstand-Ausrüstung pflicht. Tank hält Saphiron mit Kopf weg vom Raid, in der Flugphase alle verteilt und dann hinter Eisblock."] },
