			text = { L["Kel'Thuzad + Adds"], "", L["- Phase 1: Skelette, Abscheulichkeiten und Seelenweber -> am Rand der Nischen töten."], L["- Frostblitz: sehr hoher Schaden -> unterbrechen."], L["- Frostschlag/Detonieren von Mana/Schattenspalt: Frost-Wurzeln, Manaexplosion und Bodenflächen -> heilen, Manaspieler raus, Spalt verlassen."], L["- Ketten von Kel'Thuzad: Gedankenkontrolle -> Spieler kontrollieren."], L["- Phase 3 (45 %): Wächter von Eiskrone -> Priester fesseln die Untoten."], "", L["Taktik: Raid verteilt in den Nischen, Unterbrecher-Rotation auf Frostblitz. Phase 3: Wächter per Untote fesseln binden."] },
