			wichtig = L["Wichtig: Stoß-Abfänger sind Offtanks/Plattenträger mit viel Leben, je mit festem Heiler. Jagdphase: Fixiertes Ziel kitet weg vom Raid, niemand läuft zum Ziel. Nahkampf rechtzeitig aus Vulkanen."],
			post = { L["SUPREMUS: Jagdphase - Ziel rennt! Aus Feuer und Vulkanen raus!"], L["Tankphase: Stoß-Abfänger im Nahkampf voll heilen."] },
		},
		{ e = { 603, 2475 }, name = L["Akamas Schemen"], en = "Shade of Akama", de = "Akamas Schemen",
			text = { L["Akamas Schemen + Kanalisierer und Adds der Aschenzungen"], "", L["- Kanalisierer der Aschenzungen: 6 Adds halten den Schemen gebannt -> alle Kanalisierer töten, dann wird der Schemen angreifbar."], L["- Zauberer der Aschenzungen: kommen aus den Seitentüren und kanalisieren ebenfalls -> sofort töten."], L["- Weitere Adds (Verteidiger, Elementaristen, Geistbinder) aus den Seitentüren -> an den Türen abfangen und tanken."], L["- Akama darf nicht sterben -> Schemen nach dem Freikommen schnell übernehmen und töten."], "", L["Taktik: Zwei Gruppen an den Seitentüren fangen Adds ab, der Rest tötet die Kanalisierer; danach alles auf den Schemen, Akama hilft mit."] },
			wichtig = L["Wichtig: Kampf startet erst beim Ansprechen von Akama – vorher Türteams aufstellen. Priorität: Zauberer/Kanalisierer vor allen anderen Adds, Verteidiger an den Türen binden. Stirbt Akama, ist es ein Wipe."],
			post = { L["SCHEMEN: Kanalisierer und Zauberer zuerst! Türgruppen Adds abfangen!"], L["Akama am Leben halten. Danach alles auf den Schemen."] },
		},
		{ e = { 604, 2476 }, name = L["Teron Blutschatten"], en = "Teron Gorefiend", de = "Teron Blutschatten",
			text = { L["Teron Blutschatten + Schattenhafte Konstrukte"], "", L["- Schatten des Todes: Spieler stirbt nach kurzer Zeit und wird zum Geist -> als Geist mit den Geisterfähigkeiten die Konstrukte verlangsamen und töten."], L["- Schattenhafte Konstrukte: greifen den Raid an -> von Geistern binden, verlangsamen und töten lassen, nicht zum Raid laufen lassen."], L["- Verbrennen: Magie-Debuff mit Feuerschaden -> bannen."], L["- Zermalmende Schatten: Schattenschaden auf mehrere Spieler -> Heiler reagieren schnell."], L["- Schicksalsblüten: schießen Schattenblitze -> Schaden heilen."], "", L["Taktik: Teron am Rand tanken; Spieler mit Schatten des Todes stellen sich vor dem Tod an die Konstrukt-Position und erledigen die Adds als Geist."] },
			wichtig = L["Wichtig: Wer Schatten des Todes hat, geht vor Ablauf zu den Konstrukten und nutzt als Geist die Leiste (Verlangsamen, Angriffe). Verbrennen sofort bannen (Priester/Paladine). Konstrukte nie den Raid erreichen lassen."],
			post = { L["TERON: Schatten des Todes - zu den Konstrukten gehen! Als Geist Adds töten!"], L["Verbrennen bannen. Konstrukte vom Raid fernhalten."] },
		},
		{ e = { 605, 2477 }, name = L["Gurtogg Siedeblut"], en = "Gurtogg Bloodboil", de = "Gurtogg Siedeblut",
			text = { L["Gurtogg Siedeblut"], "", L["- Blutsieden: trifft die 5 entferntesten Spieler, Debuff stapelt -> 3 Fernkampfgruppen im Wechsel hinten stehen."], L["- Teufelssäure / Säurewunde: stapelnde Rüstungsreduktion am Tank -> Tankwechsel."], L["- Rauswerfen: Rückstoß mit Bedrohungsverlust -> zweiter Tank sofort übernehmen."], L["- Teufelswut (Phase 2): fixiert einen zufälligen Spieler, der viel Leben und Rüstung bekommt -> diesen Spieler stark heilen, Raid weiter auf Boss."], L["- Teufelsgeysir: Schaden um den Fixierten -> nicht zu nah stehen."], "", L["Taktik: Zwei Tanks wechseln wegen der Säure, Fernkampf in Gruppen für Blutsieden rotieren; in Teufelswut den Fixierten hochheilen."] },
			wichtig = L["Wichtig: Blutsieden-Gruppen fest einteilen und nach wenigen Stapeln wechseln. Zweiter Tank immer auf Platz 2 der Bedrohung (Rauswerfen). Teufelswut: Fixierter bleibt stehen, Heiler konzentrieren sich auf ihn."],
			post = { L["GURTOGG: Blutsieden-Gruppen rotieren! Tankwechsel bei Säurestapeln!"], L["Teufelswut: Fixiertes Ziel voll heilen, nicht wegrennen."] },
