		{ e = { 606, 2478 }, name = L["Reliquiar der Seelen"], en = "Reliquary of Souls", de = "Reliquiar der Seelen",
			text = { L["Reliquiar der Seelen (Essenz des Leidens, der Begierde, des Zorns)"], "", L["- Essenz des Leidens: Aura senkt Heilung massiv, fixiert den nächsten Spieler -> Nahkämpfer mit hohem Leben vorne, schnell töten."], L["- Gefangene Seelen zwischen den Phasen: Adds -> schnell töten."], L["- Essenz der Begierde: Aura reflektiert Schaden auf den Angreifer und senkt Mana -> Schaden dosieren; Runenschild bannen, Abstumpfen und Geistschock unterbrechen."], L["- Essenz des Zorns: Bosheit auf mehrere Spieler -> heilen; Seelenschrei entzieht Mana -> Mana sparen."], L["- Zorn steigert sich bei Tankwechsel -> nur einen Tank verwenden."], "", L["Taktik: Drei Phasen nacheinander: Leiden schnell töten, Begierde kontrolliert mit Unterbrechern, Zorn mit vollem Raid-Schaden."] },
			wichtig = L["Wichtig: P1 Nahkämpfer mit viel Leben vorne. P2: Runenschild bannen (Priester), Abstumpfen und Geistschock fest rotierend unterbrechen, Schaden drosseln. Vor P3 Mana auffüllen (Seelenschrei)."],
