		},
		{ e = { 607 }, name = L["Mutter Shahraz"], en = "Mother Shahraz", de = "Mutter Shahraz",
			text = { L["Mutter Shahraz"], "", L["- Unheilvoller, Übler, Gemeiner, Sündiger Strahl: Schattenschaden und Debuffs -> Raid mit Schattenwiderstand."], L["- Tödliche Anziehung: 3 Spieler werden zusammen teleportiert und schaden sich gegenseitig -> sofort auseinander laufen."], L["- Säbelpeitsche: Schaden wird auf Umstehende aufgeteilt -> Nahkampf und Tanks zusammen am Boss."], L["- Prismatische Aura: wechselnde Widerstände -> keine Gegenmaßnahme nötig."], L["- Raserei bei ca. 10% -> Cooldowns aufheben."], "", L["Taktik: Boss mittig tanken, Nahkampf zum Teilen der Säbelpeitsche stapeln, Raid mit Schattenwiderstand-Ausrüstung verteilt."] },
			wichtig = L["Wichtig: Schattenwiderstand-Buffs (Gebet des Schattenschutzes, Aura, Totem) Pflicht. Anziehungs-Ziele laufen sofort in verschiedene Richtungen weg vom Raid. Nahkampf eng stapeln (Säbelpeitsche), CDs ab 10%."],
			post = { L["SHAHRAZ: Bei Anziehung SOFORT auseinander laufen!"], L["Nahkampf am Boss für Säbelpeitsche. Schattenwiderstand an."] },
		},
		{ e = { 608, 2480 }, name = L["Rat der Illidari"], en = "Illidari Council", de = "Rat der Illidari",
			text = { L["Rat der Illidari (Gathios, Malande, Zerevor, Veras)"], "", L["- Gemeinsamer Lebenspool: alle vier teilen sich das Leben -> Schaden verteilen ist egal, alle sterben zusammen."], L["- Gathios der Zerschmetterer: Weihe und Segen/Auren -> Segen und Schutz stehlen/reinigen, von Weihe weg tanken."], L["- Lady Malande: Gebet der Heilung, Göttlicher Zorn, Reflexionsschild -> Heilzauber unterbrechen, Schild beachten."], L["- Hochnethermant Zerevor: Arkane Explosion, Blizzard, Flammenstoß -> auf Distanz halten (Magier/Hexer-Tank), aus Flächenschaden raus."], L["- Veras Dunkelschatten: Verschwinden und tödliches Gift -> Gift entfernen, Ziel heilen."], "", L["Taktik: Jedes Ratsmitglied eigener Tank an eigener Position, Zerevor auf Distanz; Malandes Heilungen konsequent unterbrechen."] },
			wichtig = L["Wichtig: Magier tankt Zerevor auf Distanz, Hexer legt Fluch der Sprachen auf ihn. Feste Unterbrecher-Rotation auf Malande (Gebet der Heilung, Göttlicher Zorn). Gathios' Segen per Zauberraub/Läutern entfernen."],
			post = { L["RAT: Malande unterbrechen! Zerevor-AoE meiden!"], L["Gift von Veras entfernen. Segen von Gathios stehlen/reinigen."] },
			marker = { name = L["Rat (Tanks)"], order = { 8, 7, 6, 5 }, note = L["Ein Symbol pro Ratsmitglied für die Tankzuteilung: Totenkopf Gathios, Kreuz Malande, Viereck Zerevor, Mond Veras."] },
		},
		{ e = { 609, 2481 }, name = L["Illidan Sturmgrimm"], en = "Illidan Stormrage", de = "Illidan Sturmgrimm",
			text = { L["Illidan Sturmgrimm + Flammen von Azzinoth und Schattendämonen"], "", L["- Scheren: senkt das max. Leben des Tanks stark -> Tank nutzt Verteidigungs-CDs, Heiler bereit."], L["- Parasitärer Schattenteufel: Spieler bekommt Debuff, Adds schlüpfen -> Adds sofort töten."], L["- Phase 2 (Flammen von Azzinoth): zwei Elementare -> mit Feuerwiderstand-Tanks getrennt tanken, nicht zu nah an die Gleven ziehen."], L["- Augenstrahl / Feuerbälle: Linie aus Feuer am Boden -> ausweichen."], L["- Dämonenform: Schattendämonen fixieren Spieler -> sofort töten; Fernkampf verteilt (Flammenexplosion)."], L["- Maiev (ab ca. 30%): legt Käfigfallen -> Illidan in die Falle ziehen."], "", L["Taktik: Phasen 1-5: Tankphase, Flammenphase mit Feuerwiderstands-Tanks, wieder Tank, Dämonenform mit Hexer-Tank, Maiev-Phase mit Fallen."] },
			wichtig = L["Wichtig: Flammen-Tanks mit Feuerwiderstand, Flammen nicht zu weit von ihrer Gleve ziehen (sonst Raserei). Dämonenform: Hexer-Tank mit Schattenwiderstand. Schattendämonen sofort töten, sonst stirbt ihr Ziel."],
			post = { L["ILLIDAN: Scheren - Tank-CDs! Schattenteufel und Dämonen sofort töten!"], L["Flammen getrennt tanken, Augenstrahl ausweichen. Maiev: Falle nutzen."] },
			marker = { name = L["Illidan"], order = { 8, 7 }, note = L["Totenkopf und Kreuz auf die beiden Flammen von Azzinoth (je ein Tank)."] },
		},
	},
})

