			text = { L["Rat der Blutprinzen: Valanar, Keleseth, Taldaram"], "", L["- Nur ein Prinz ist verstärkt und nimmt echten Schaden -> Ziel beim Wechsel umstellen."], L["- Valanar: Schockwirbel, verstärkt als großer Raidwirbel -> verteilen und aus Wirbeln raus."], L["- Keleseth: Schattenlanze und Dunkle Kerne -> von einem Fernkampf-Tank (z. B. Hexer) gehalten, Kerne mitnehmen."], L["- Taldaram: Flammenkugel verfolgt einen Spieler -> Ziel zieht sie vom Raid weg."], L["- Kinetische Bomben: fallen langsam -> durch Fernkampf in der Luft halten, nicht aufschlagen lassen."], "", L["Taktik: Valanar und Taldaram von Nahkampf-Tanks, Keleseth vom Fernkampf-Tank; nur den verstärkten Prinzen voll beschießen, Bomben oben halten, Flammenkugeln kiten."] },
			wichtig = L["Wichtig: Keleseth-Tank (Hexer/Paladin) sammelt Dunkle Kerne, nur den Prinzen mit Blutanrufung voll beschießen. Feste Fernkämpfer halten Kinetische Bomben oben; Heroisch Schattengefängnis: kaum bewegen."],
			post = { L["BLUTPRINZEN: Nur auf den verstärkten Prinzen! Kinetische Bomben oben halten!"], L["Flammenkugel wegziehen. Bei Valanar-Wirbel verteilen."] },
		},
		{ e = { 853, 1103 }, name = L["Blutkönigin Lana'thel"], en = "Blood-Queen Lana'thel", de = "Blutkönigin Lana'thel",
			text = { L["Blutkönigin Lana'thel"], "", L["- Essenz der Blutkönigin: gebissene Spieler müssen nach einiger Zeit einen anderen Spieler beißen -> feste Beißliste, sonst Gedankenkontrolle."], L["- Pakt der Dunkelgefallenen: verbundene Spieler nehmen Schaden -> sofort zueinander laufen."], L["- Schwärmende Schatten: Ziel hinterlässt Schattenpfütze -> am Rand ablegen, nicht durch den Raid laufen."], L["- Luftphase: Blutwirbel und Furcht -> verteilt stehen, Heiler bereit."], "", L["Taktik: Boss zentral tanken, Fernkampf locker verteilt, Schatten an den Rand. Beißreihenfolge vorher festlegen (Schaden zuerst), Pakt-Spieler treffen sich sofort."] },
			wichtig = L["Wichtig: Beißliste vorher festlegen (Schaden zuerst, Heiler zuletzt); wer zu spät beißt, wird gedankenkontrolliert. Pakt-Spieler sofort zusammen, Schwärmende Schatten zum Rand. In der Luftphase verteilen."],
			post = { L["LANA'THEL: Beißliste einhalten! Pakt-Ziele sofort zueinander!"], L["Schwärmende Schatten an den Rand legen. Luftphase verteilt stehen."] },
		},
		{ e = { 854, 1098 }, name = L["Valithria Traumwandler"], en = "Valithria Dreamwalker", de = "Valithria Traumwandler",
			text = { L["Valithria Traumwandler + untote Adds aus den Portalen"], "", L["- Ziel: Valithria auf 100 % heilen -> Heiler heilen nur sie, Schaden auf die Adds."], L["- Traumportale: Heiler fliegen in die Traumwelt und sammeln Nebelwolken -> starker Heilungsbonus."], L["- Unterdrücker: reduzieren die Heilung auf Valithria -> schnell töten bzw. kontrollieren."], L["- Brennende Skelette und Erzmagier: hoher Schaden/Raid-AoE -> sofort töten, Frostbomben-Zielen ausweichen."], L["- Verderbte Abscheulichkeiten/Zombies: verlangsamen bzw. explodieren -> von Tanks gehalten, außerhalb des Raids töten."], "", L["Taktik: Raid in zwei Gruppen an beiden Seiten für die Portale, Tanks sammeln die Adds. Heiler rotieren durch die Traumwelt, DPS fokussiert Unterdrücker und Skelette."] },
			wichtig = L["Wichtig: Heiler heilen nur Valithria und fliegen nach Plan in die Portale. DPS: Unterdrücker betäuben und zuerst töten, Erzmagier-Frostblitzsalve unterbrechen, Skelette schnell; Zombies/Abscheulichkeiten vom Raid weg."],
			post = { L["VALITHRIA: Heiler nur auf Valithria! Unterdrücker und Skelette zuerst!"], L["Heiler in die Portale, Nebel sammeln. Adds weg vom Raid tanken."] },
		},
		{ e = { 855, 1105 }, name = L["Sindragosa"], en = "Sindragosa", de = "Sindragosa",
			text = { L["Sindragosa"], "", L["- Entfesselte Magie: Zauberer erleiden Schaden pro Zauber -> bei hohen Stapeln kurz nicht zaubern; Nahkampf achtet auf Frost-Stapel (Bis auf die Knochen)."], L["- Durchdringende Kälte (Blistering Cold): großer Schaden im Nahbereich nach Eisgriff -> sofort mindestens 25 m weg vom Boss."], L["- Frostleuchtfeuer: Ziele werden zu Eisgräbern -> in festgelegter Formation stehen, Gräber zum Sichtschutz nutzen."], L["- Luftphase: Frostbomben -> hinter Eisgrab verstecken, danach Gräber freischlagen."], L["- Phase 3 (35 %): Mysteriöse Energie stapelt auf Spielern -> per Sichtlinie hinter Eisgrab zurücksetzen."], "", L["Taktik: Boss seitlich tanken, Raid hinter ihr gestaffelt. Eisgräber nach Plan platzieren, in P3 Tankwechsel und Stapel per Grab-Sichtschutz abbauen."] },
			wichtig = L["Wichtig: Frostresistenz (Paladin-Aura/Schamanen-Totem) aktiv. Entfesselte-Magie-Ziele hören bei hohen Stapeln auf zu zaubern, Nahkampf pausiert bei Kälte-Stapeln. P3 Mystischer Puffer: Grab-Sichtschutz + Tankwechsel."],
			post = { L["SINDRAGOSA: Nach Eisgriff sofort weg vom Boss! Frostbombe: hinter Eisgrab!"], L["Entfesselte Magie: weniger zaubern. P3 Stapel hinter Gräbern abbauen."] },
		},
		{ e = { 856, 1106 }, name = L["Der Lichkönig"], en = "The Lich King", de = "Der Lichkönig",
			text = { L["Der Lichkönig + Ghule, Schreckliche Schrecken, Val'kyr, Eissphären, Wütende Geister"], "", L["- Phase 1: Nekrotische Seuche springt beim Bannen -> auf einen Schrecklichen Schrecken bannen; Schrecken-Raserei per Einlullen beruhigen."], L["- Zwischenphasen: Unbarmherziger Winter -> an den Rand, Eissphären und Wütende Geister töten bzw. ausweichen."], L["- Phase 2: Val'kyr tragen Spieler zum Rand -> sofort töten bzw. verlangsamen; Entweihen -> aus dem Kreis raus, am Rand ablegen."], L["- Phase 3: Seele ernten zieht Spieler in Frostgram -> dort Geist töten/überleben; Üble Geister -> wegkiten, nicht berühren."], L["- Zersprengen (Infest): Raidweiter Schaden -> Raid über 90 % hochheilen."], "", L["Taktik: Boss am Rand vom Eingang tanken, Adds sauber töten. P2 Val'kyr fokussieren und Entweihen am Rand ablegen, P3 Geister kiten und Seele ernten mit Abklingzeiten überbrücken."] },
			wichtig = L["Wichtig: Nekrotische Seuche nur neben einem Schrecken bannen, Jäger beruhigen dessen Raserei. Seelenernter auf dem Tank: sofort Tankwechsel. Val'kyr betäuben/verlangsamen, Entweihen-Ziel läuft sofort raus."],
			post = { L["LICHKÖNIG: Val'kyr sofort töten! Entweihen am Rand ablegen!"], L["Seuche auf Schrecken bannen. Winter: an den Rand, Sphären/Geister töten."] },
			marker = { name = L["Val'kyr"], order = { 8, 7, 6 }, note = L["Totenkopf, Kreuz und Viereck auf die Val'kyr in Phase 2, in dieser Reihenfolge töten bzw. verlangsamen."] },
		},
	},
})

