			wichtig = L["Wichtig: Splitter-Soak strikt nach Rotation, nie mit Gequält-Debuff soaken. Bei Dezimierungsklinge Tank sofort hochheilen, bei Inferno-Klinge Tank-CDs. Raid steht hinter dem Boss; Heiler nutzen ihre Funken-Stapel."],
			post = { L["BALOROC: Kristall-Rotation einhalten!"], L["Dezimierungsklinge: Tank sofort hochheilen."] },
