		{ e = { 2070 }, j = 1997, en = "Antoran High Command", de = "Antorisches Oberkommando",
			text = { L["Admiral Svirax + Chefingenieur Ishkar + General Erodus + Adds"], "", L["- Kommandokapseln: ein aktiver Offizier kämpft, die anderen sitzen in Kapseln -> Spieler nutzen freie Kapseln für zusätzliche Fähigkeiten (z. B. Schild gegen Salve)."], L["- Salve (Svirax): hoher Raidschaden -> Raid stellt sich in den Schild des Kapselspielers oder nutzt Cooldowns."], L["- Entropische Minen (Ishkar): Minen am Boden -> nicht hineinlaufen, gezielt räumen."], L["- Verstärkung (Erodus): Teufelsklingen-Stoßtruppler und Pyromanten -> Adds schnell töten, Zauber unterbrechen."], L["- Schwäche ausnutzen: Tank-Debuff -> Tankwechsel nach Stapeln."], "", L["Taktik: Aktiven Offizier fokussieren, Adds sofort umschalten. Kapselspieler fest einteilen und ihre Fähigkeiten auf Ansage nutzen."] },
			wichtig = L["Wichtig: Kapsel-Spieler und ihre Fähigkeiten fest einteilen. Raid steht bei Salve im Schild. Pyromanten unterbrechen, Stoßtruppler sofort töten. Tankwechsel nach Stapeln. Minen gezielt räumen."],
			post = { L["OBERKOMMANDO: Adds sofort töten, bei Salve in den Schild!"], L["Kapselspieler nach Plan, Minen meiden. Tankwechsel nach Stapeln."] },
			marker = { name = L["Oberkommando"], order = { 8, 7, 6 }, note = L["Totenkopf auf den aktiven Offizier, Kreuz und Viereck auf die Adds in Tötungsreihenfolge."] },
		},
		{ e = { 2064 }, j = 1985, en = "Portal Keeper Hasabel", de = "Portalhüterin Hasabel",
			text = { L["Portalhüterin Hasabel + Portalwelten (Xoroth, Rancora, Nathreza)"], "", L["- Riss in der Realität: Tank-Debuff -> Tankwechsel nach Stapeln."], L["- Zusammenbrechende Welt: Einschlagzone vor dem Boss -> herauslaufen."], L["- Teufelssturm-Sperrfeuer: Linien quer durch den Raum -> ausweichen."], L["- Portale: Hasabel öffnet Portale zu drei Welten, deren Wächter Adds herüberschicken -> Portal-Teams gehen hinein, töten den Wächter und schließen das Portal."], L["- Adds der Welten (z. B. Wichtel, Vulkanare): gefährliche Fähigkeiten -> unterbrechen und schnell töten."], "", L["Taktik: Kleine Teams (meist 3-5 Spieler mit Heiler) für die Portale einteilen, der Rest bleibt am Boss. Portale zügig schließen, sonst steigt der Raidschaden stark an."] },
			wichtig = L["Wichtig: Portal-Teams mit Heiler fest einteilen, Reihenfolge der Welten vorher festlegen. Adds der Welten unterbrechen. Tankwechsel nach Riss-Stapeln. Raid am Boss weicht Linien aus. Offene Portale = Wipe."],
			post = { L["HASABEL: Portal-Teams rein, Wächter töten, Portal schließen!"], L["Linien ausweichen, Adds unterbrechen. Tankwechsel nach Riss."] },
			marker = { name = L["Hasabel (Portale)"], order = { 8, 7, 6 }, note = L["Totenkopf, Kreuz und Viereck markieren die drei Portale (Xoroth, Rancora, Nathreza) für die Teams."] },
		},
		{ e = { 2075 }, j = 2025, en = "Eonar the Life-Binder", de = "Eonar die Lebensbinderin",
			text = { L["Essenz von Eonar + Wellen der Legion"], "", L["- Essenz von Eonar: muss überleben -> Heiler heilen die Essenz, Adds dürfen sie nicht erreichen."], L["- Drei Wege (oben, Mitte, unten): Adds kommen über verschiedene Pfade -> Gruppen fest auf die Wege verteilen."], L["- Teufelszerstörer und Verhüller: starke Adds mit Schilden/Unsichtbarkeit -> priorisiert töten."], L["- Läuterer: Adds, die die Essenz angreifen -> sofort töten."], L["- Paraxis-Beschuss (Regen des Teufels, Speer der Verdammnis): Einschläge und Linien -> ausweichen."], "", L["Taktik: Raid in Teams aufteilen und mit den Sprungfeldern zu den Wegen wechseln. Heiler halten die Essenz hoch und kümmern sich zusätzlich um den Raid."], L["Mythisch: Paraxis muss zusätzlich beschädigt werden (Spieler fliegen hoch), dafür eigenes Team einteilen."] },
			wichtig = L["Wichtig: Wege-Teams fest einteilen, Heiler-Kontingent für die Essenz. Verhüller und Teufelszerstörer zuerst, Läuterer sofort töten. Einschlägen und Speer ausweichen. Mythisch: eigenes Paraxis-Team einteilen."],
			post = { L["EONAR: Adds auf allen Wegen töten, Essenz am Leben halten!"], L["Teams auf ihre Wege, Läuterer sofort töten. Einschlägen ausweichen."] },
		},
		{ e = { 2082 }, j = 2009, en = "Imonar the Soulhunter", de = "Imonar der Seelenjäger",
			text = { L["Imonar der Seelenjäger"], "", L["- Schocklanze: Tank-Debuff -> Tankwechsel nach Stapeln."], L["- Schlafkanister: Spieler schläft ein -> nicht in der Nähe anderer stehen, Heiler bannen erst, wenn der Spieler allein steht."], L["- Pulsgranate: Flächenschaden an markierter Stelle -> ausweichen."], L["- Zwischenphasen: Imonar flieht über die Brücke und legt Fallen -> Fallen ausweichen und ihm folgen."], L["- Spätere Phasen: Sprengsprengladungen und Feuer -> sauber laufen, Raidschaden steigt."], "", L["Taktik: Boss am Rand der Plattform tanken, Raid locker verteilt. In den Zwischenphasen gemeinsam über die Brücke laufen und Fallen meiden."] },
			wichtig = L["Wichtig: Schlafende erst bannen, wenn sie allein stehen; Bann-Heiler festlegen. Tankwechsel nach Schocklanze. Zwischenphasen: gemeinsam laufen, Fallen meiden. Raid-Cooldowns für späte Phasen planen."],
			post = { L["IMONAR: Schlafende Spieler weg vom Raid, dann bannen!"], L["Zwischenphase: Fallen ausweichen, Boss folgen. Tankwechsel nach Schocklanze."] },
		},
		{ e = { 2088 }, j = 2004, en = "Kin'garoth", de = "Kin'garoth",
			text = { L["Kin'garoth + Konstrukte"], "", L["- Verheerer: Strahl fegt über die Plattform -> ausweichen."], L["- Diabolische Bombe: Bomben müssen gesoakt werden -> mehrere Spieler pro Bombe."], L["- Schmiedeschlag / Widerhallender Schlag: starke Tank-Treffer -> Tankwechsel."], L["- Abriss: markierte Spieler -> gemeinsam soaken lassen, nicht weglaufen."], L["- Initialisierungsphase: Konstrukte (Dezimator, Annihilator, Abrissmaschine) werden gebaut -> vorher Schaden aufbauen, Konstrukte schnell zerstören."], "", L["Taktik: In der Initialisierungsphase die Konstrukte fokussieren, in der Angriffsphase Bomben soaken und Verheerer ausweichen. Tanks wechseln nach jedem schweren Schlag."] },
			wichtig = L["Wichtig: Konstrukte vor Ende der Initialisierung zerstören, Schadens-Cooldowns dafür sparen. Bomben mit mehreren Spielern soaken. Abriss-Ziele sammeln sich. Tankwechsel nach Schlag. Verheerer-Strahl ausweichen."],
			post = { L["KIN'GAROTH: Konstrukte schnell zerstören, Bomben soaken!"], L["Verheerer ausweichen. Tankwechsel nach Schlag."] },
			marker = { name = L["Kin'garoth"], order = { 8, 7, 6 }, note = L["Totenkopf, Kreuz und Viereck auf die Konstrukte in Tötungsreihenfolge."] },
		},
		{ e = { 2069 }, j = 1983, en = "Varimathras", de = "Varimathras",
			text = { L["Varimathras"], "", L["- Qualen (Flammen, Frost, Teufel, Schatten): wechselnde Umgebungsgefahr -> auf die jeweilige Mechanik achten (z. B. Feuer am Boden, Frost-Zonen)."], L["- Elend: Spieler werden getroffen -> nicht in andere Spieler hineinlaufen."], L["- Dunkle Spalte: Flächen am Boden -> herausgehen."], L["- Nekrotische Umarmung: Debuff springt auf nahe Spieler -> Spieler mit Debuff steht allein am Rand."], L["- Tank-Mechanik (Schattenstoß / Allein in der Finsternis): Tanks müssen nahe beieinander stehen -> Tankwechsel nach Ansage."], "", L["Taktik: Boss in der Mitte tanken, Raid verteilt. Debuff-Spieler sofort raus, Heiler-Cooldowns für die späten Qualen planen."] },
			wichtig = L["Wichtig: Tanks immer in Reichweite zueinander (Allein in der Finsternis). Nekrotische Umarmung: Ziel steht allein. Elend-Ziele nicht in andere laufen. Spalten meiden. Heiler-Cooldowns für späte Qualen."],
			post = { L["VARIMATHRAS: Nekrotische Umarmung sofort weg vom Raid!"], L["Spalten meiden, Tanks nah zusammen. Auf aktuelle Qual achten."] },
		},
		{ e = { 2073 }, j = 1986, en = "The Coven of Shivarra", de = "Der Zirkel der Shivarra",
			text = { L["Asara + Noura + Diima + Thu'raya (Zirkel der Shivarra)"], "", L["- Qualen der Titanen: Geister von Aman'Thul, Khaz'goroth, Golganneth und Norgannon greifen nacheinander an -> je nach Titan Linien, Kugeln oder Stürmen ausweichen."], L["- Wirbelnder Säbel / Feuriger Schlag: Tank-Fähigkeiten -> Tankwechsel."], L["- Explodierender Puls (Noura): Spieler explodieren -> verteilt stehen."], L["- Gekühltes Blut (Diima): Heilabsorption -> gezielt wegheilen."], L["- Sturm der Dunkelheit (Asara): Raidschaden -> im Schutzbereich stehen."], "", L["Taktik: Immer nur die aktiven Schwestern angreifen, Schaden auf die gefährlichste fokussieren. Raid verteilt, Heiler priorisieren Gekühltes Blut."] },
			wichtig = L["Wichtig: Nur die aktiven Schwestern angreifen. Heiler priorisieren Gekühltes Blut. Raid verteilt für Explodierenden Puls. Titan-Mechaniken vorher kennen. Tankwechsel nach Ansage."],
			post = { L["ZIRKEL: Titan-Geistern ausweichen, Gekühltes Blut wegheilen!"], L["Verteilt stehen. Tankwechsel nach Ansage."] },
			marker = { name = L["Zirkel der Shivarra"], order = { 8, 7, 6, 5 }, note = L["Je ein Symbol pro Schwester (Totenkopf Asara, Kreuz Noura, Viereck Diima, Mond Thu'raya)."] },
		},
		{ e = { 2063 }, j = 1984, en = "Aggramar", de = "Aggramar",
			text = { L["Aggramar + Glut von Taeshalach"], "", L["- Taeshalachs Reichweite: stapelnder Tank-Debuff -> Tankwechsel."], L["- Taeshalachs Technik: Kombo aus Flammenriss (Soak vor dem Boss), Tempest/Feuerwellen und Wuchtschlag -> Ansage folgen, Flammenriss mit vielen Spielern soaken."], L["- Sengende Flammen: Feuerflächen -> herauslaufen."], L["- Zwischenphasen (80 % / 40 %): Glut von Taeshalach erscheint -> Glut töten, bevor sie den Boss erreicht."], L["- Wogende Flammen: Linien am Boden -> ausweichen."], "", L["Taktik: Raid hinter dem Boss, Nahkampf/Fernkampf soaken die Flammenrisse nach Einteilung. In den Zwischenphasen alle Gluten verlangsamen und töten."] },
			wichtig = L["Wichtig: Raidleiter sagt jede Technik-Kombo an. Flammenriss nur von eingeteilten Soakern. Tankwechsel nach Reichweite-Stapeln. Zwischenphase: Gluten verlangsamen und töten, bevor sie den Boss erreichen."],
			post = { L["AGGRAMAR: Flammenriss soaken, in Zwischenphasen Glut töten!"], L["Feuerlinien ausweichen. Tankwechsel nach Stapeln."] },
		},
		{ e = { 2092 }, j = 2031, en = "Argus the Unmaker", de = "Argus der Zerrütter",
			text = { L["Argus der Zerrütter + Konstellare und Adds"], "", L["- Schwungvolle Sense: stapelnder Tank-Debuff -> Tankwechsel."], L["- Seelenfäule: Spieler mit Debuff -> raus aus dem Raid, Kugeln nicht treffen lassen."], L["- Geschenk des Himmels / des Meeres: Spieler mit diesen Buffs -> getrennt voneinander stehen, Rest verteilt."], L["- Seelenbombe / Seelenexplosion (Phase 2): markierte Spieler -> nach Plan weglaufen bzw. sammeln."], L["- Phase 3: Pantheon-Konstellaren und Module -> Adds töten, Seelen der Pantheon nutzen."], "", L["Taktik: Mehrphasiger Endkampf mit Tankwechseln und vielen Positionen; Debuff-Spieler laufen vor dem Ablauf raus. Raid-Cooldowns für die Phasenübergänge planen."] },
			wichtig = L["Wichtig: Himmel- und Meer-Träger immer getrennt. Seelenfäule-Ziele vor Ablauf raus. Seelenbombe-Ziel weit weg. Tankwechsel nach Sense. Raid-Cooldowns für Phasenübergänge; Heldentum meist am Ende."],
			post = { L["ARGUS: Debuff-Spieler raus, Himmel und Meer getrennt!"], L["Phasen nach Plan, Adds schnell töten. Tankwechsel nach Sense."] },
		},
	},
})

