			post = { L["SCHRILLSCHWINGE: Bei Kreischen HINTER DIE SÄULEN! Pfützen am Rand ablegen."], L["Tankwechsel bei Biss-Stapeln. Phase 2: Säulen nutzen, Wellen ausweichen."] },
		},
