			wichtig = L["Wichtig: Okkultisten mit fester Kick-Reihenfolge. Seeleninfusoren stunnen/verlangsamen, bevor sie Kael erreichen. Phönixe abseits töten. Glutstoß mit vielen Spielern teilen. Schatten von Kael'thas sofort fokussieren."],
			post = { L["KAEL'THAS: Adds töten, Kael'thas heilen! Glutstoß gemeinsam teilen."], L["Okkultisten unterbrechen. Schatten von Kael'thas sofort fokussieren."] },
