			wichtig = L["Wichtig: Portalträger stellen sich weit auseinander und sagen Position an. Geister in Stasisfallen führen. Glyphe-Tank weit raus. Bei Rand der Vernichtung rechtzeitig durchs Portal. Saaten nicht neben dem Raid explodieren lassen."],
			post = { L["XY'MOX: Portale weit auseinander! Glyphe -> Tank weg vom Raid."], L["Fallen meiden. Bei Saat und Rand der Vernichtung per Portal auf die sichere Seite."] },
			marker = { name = L["Xy'mox (Portale)"], order = { 1, 2 }, note = L["Stern und Kreis zeigen die beiden Spieler mit Dimensionsriss (Portal-Endpunkte)."] },
		},
		{ e = { 2383 }, j = 2428, en = "Hungering Destroyer", de = "Hungernder Zerstörer",
			text = { L["Hungernder Zerstörer"], "", L["- Völlerei-Miasma: Heilungsabsorption auf mehreren Spielern -> gezielt durchheilen, Träger nicht sterben lassen."], L["- Verschlingen: zieht alle Spieler zum Boss -> dagegen weglaufen, Bewegungsfähigkeiten nutzen."], L["- Austreiben: Schaden um markierte Spieler -> verteilen."], L["- Verwüsten: Schaden wird auf alle getroffenen Spieler geteilt -> geschlossen stacken."], L["- Flüchtiger Auswurf: Strahlen auf markierte Spieler -> vom Raid weg ausrichten."], L["- Überwältigen: schwerer Tankschlag -> Tankwechsel."], "", L["Taktik: Raid geschlossen hinter dem Boss, bei Verschlingen gemeinsam weglaufen, Auswurf-Ziele stellen sich vorher abseits auf."] },
			wichtig = L["Wichtig: Miasma-Träger gezielt durchheilen, Externs einplanen. Verschlingen: Bewegungsfähigkeiten aufheben. Auswurf-Ziele stellen sich vorher abseits. Verwüsten: Raid geschlossen. Überwältigen: Tankwechsel."],
			post = { L["ZERSTÖRER: Bei Verschlingen weglaufen! Auswurf-Strahlen weg vom Raid."], L["Miasma-Ziele gezielt heilen. Tankwechsel bei Überwältigen."] },
