			wichtig = L["Wichtig: Behälter-Reihenfolge vorher festlegen, ein Spieler sagt an. Konzentrierte Anima: Adds sofort fokussieren. Geteiltes Leid mit mehreren Spielern tragen. Tankwechsel nach Stapeln. Abgefüllte Anima ausweichen."],
			post = { L["INERVA: Adds sofort töten! Geteiltes Leid gemeinsam tragen."], L["Tankwechsel bei Stapeln. Anima-Geschossen ausweichen."] },
			marker = { name = L["Inerva (Adds)"], order = { 8, 7, 6, 5 }, note = L["Symbole auf die beschworenen Anima-Adds in Tötungsreihenfolge, Totenkopf zuerst."] },
		},
		{ e = { 2412 }, j = 2426, en = "The Council of Blood", de = "Rat des Blutes",
			text = { L["Rat des Blutes: Baronin Frieda, Lord Stavros, Kastellan Niklaus"], "", L["- Baronin Frieda - Essenz entziehen und Stolze Eruption: Schaden auf Spieler und um den Boss -> heilen, bei Eruption weg vom Boss."], L["- Lord Stavros - Ausweichender Ausfall: Sturmangriff in Linie -> Linie meiden. Dunkles Rezital: verbundene Spieler -> zusammen laufen."], L["- Kastellan Niklaus - Pflichtbewusster Diener: Schild auf einem Boss -> sofort töten. Ausgräberdiener: Adds -> töten."], L["- Todestanz: nach jedem Bosskill -> den angezeigten Tanzschritten folgen, Fehler kosten viel Schaden."], L["- Verbleibende Bosse werden nach jedem Kill stärker -> Kill-Reihenfolge festlegen und einhalten."], "", L["Taktik: Feste Kill-Reihenfolge (meist Niklaus oder Frieda zuerst), Bosse getrennt tanken, Diener sofort töten. Beim Tanz sauber mitlaufen."], L["Heroisch/Mythisch: Tanzphasen und Rezital verlangen deutlich mehr Präzision."] },
			wichtig = L["Wichtig: Friedas Schadenssalve immer kicken – feste Kick-Reihenfolge. Diener: Fernkampf schaltet sofort um. Kill-Reihenfolge strikt einhalten. Beim Todestanz Schritte genau befolgen. Heiler-CDs für die Tanzphasen."],
			post = { L["RAT DES BLUTES: Diener sofort töten! Kill-Reihenfolge einhalten."], L["Beim Tanz den Schritten folgen. Rezital-Partner zusammenbleiben."] },
			marker = { name = L["Rat des Blutes"], order = { 8, 6 }, note = L["Totenkopf auf den Pflichtbewussten Diener, Viereck auf das Spiegelbild bzw. Zusatzziel."] },
		},
		{ e = { 2399 }, j = 2394, en = "Sludgefist", de = "Schlickfaust",
			text = { L["Schlickfaust"], "", L["- Hasserfüllter Blick: markiertes Ziel (Stern) wird angestürmt -> vor eine intakte Säule stellen, Boss prallt dagegen und ist betäubt (dann voller Schaden)."], L["- Kettenglied: Spieler paarweise verkettet -> mit dem Partner zusammenbleiben, sonst Schaden."], L["- Kettenschlag (Heroisch): markierter Spieler wird hochgeschleudert -> mit Partnern den Schaden teilen."], L["- Zerstörerisches Stampfen: Schaden um den Boss -> Nahkampf rennt kurz weg."], L["- Kolossales Gebrüll und Fallender Schutt: Raidschaden und Felsbrocken -> Defensive, ausweichen."], "", L["Taktik: Raid beim Boss, Blick-Ziel stellt sich vor eine intakte Säule, Ansturmlinie freihalten. Säulen der Reihe nach verbrauchen."], L["Mythisch: Seismische Verschiebung zwingt zusätzlich zum Verteilen."] },
			wichtig = L["Wichtig: Blick-Ziel sagt Säule an, Raid läuft geschlossen mit. Säulen sind begrenzt – keine Stuns verschwenden, Schaden in Betäubungsphasen bündeln. Kettenpartner nie trennen. Stampfen: Nahkampf kurz raus."],
			post = { L["SCHLICKFAUST: Blick-Ziel vor eine Säule! Ansturmlinie freihalten!"], L["Kettenpartner zusammen. Nahkampf bei Stampfen weg."] },
			marker = { name = L["Schlickfaust"], order = { 1 }, note = L["Stern auf das Ziel von Hasserfüllter Blick (Ansturm)."] },
		},
		{ e = { 2417 }, j = 2425, en = "Stone Legion Generals", de = "Generäle der Steinlegion",
			text = { L["Generäle der Steinlegion: General Kaal und General Grashaal + Adds"], "", L["- Herzzerreißen: Debuff auf mehreren Spielern -> gegenheilen, nach Plan bannen."], L["- Böse Klinge (Kaal): fliegt in einer Linie zum markierten Spieler -> Linie freihalten bzw. wie geplant aufstellen."], L["- Widerhallender Sprung (Grashaal): Sprung mit Schaden -> verteilen, Ziel teilt mit."], L["- Kristallisieren: markierter Spieler (Mond) -> weg vom Raid, explodiert nach kurzer Zeit."], L["- Steinlegion-Goliath und Schattenkräfte: Adds -> schnell töten."], L["- Zwischenphasen: Generäle werden unverwundbar -> Adds töten, Anweisungen zur Anima beachten."], "", L["Taktik: Erst Kaal (Phase 1), dann Grashaal, am Ende beide gemeinsam. Adds immer zuerst, Herzzerreißen kontrolliert heilen und bannen."] },
			wichtig = L["Wichtig: Herzzerreißen nach Bannliste bannen, Heiler planen. Kristallisieren-Ziel sofort weg vom Raid. Goliath-Adds zuerst. Böse Klinge: Linie freihalten. Kaal zuerst, dann Grashaal, am Ende beide gemeinsam."],
			post = { L["GENERÄLE: Adds zuerst! Böse-Klinge-Linie freihalten."], L["Herzzerreißen heilen/bannen. Kristallisieren weg vom Raid."] },
			marker = { name = L["Steinlegion Adds"], order = { 8, 7, 6 }, note = L["Totenkopf, Kreuz, Viereck auf Schattenkräfte bzw. Goliath in Tötungsreihenfolge."] },
		},
		{ e = { 2407 }, j = 2424, en = "Sire Denathrius", de = "Graf Denathrius",
			text = { L["Graf Denathrius + Remornia"], "", L["- Sündenlast (Phase 1): Stapel auf allen Spielern -> sich von Reinigender Schmerz treffen lassen, um Stapel abzubauen."], L["- Blutpreis: Schaden wird auf den Raid geteilt -> zusammen stehen."], L["- Nachtjäger: markierte Spieler (Stern, Kreis, Diamant) werden in einer Linie getroffen -> Linie mit Mitspielern teilen."], L["- Zwischenphase - Marsch der Büßer: Raid wird in den Saal geführt -> Fluss folgen, Schaden heilen."], L["- Phase 2 - Purpurne Kabalisten, Aufspießen, Hand der Zerstörung: Adds und Linien -> Adds töten, Linien meiden, bei Hand weglaufen."], L["- Phase 3 - Zerschmetternder Schmerz und Tödliche Finesse: Raidschaden und Sprünge -> verteilen, Ziele weg vom Raid."], "", L["Taktik: Phase 1: Tankwechsel, Raid baut Sündenlast ab. Phase 2/3: Adds zuerst, Linien und Hände meiden, Raidheilung mit Defensiven planen."], L["Letzter Boss von Schloss Nathria."] },
			wichtig = L["Wichtig: Phase 1: Sündenlast-Stapel kontrolliert über Reinigenden Schmerz abbauen. Kabalisten sofort umschalten. Hand der Zerstörung: alle weit weg. Phase 3: Finesse-Ziele raus, Raid-CDs pro Schmerz verteilen."],
			post = { L["DENATHRIUS: Sündenlast abbauen! Nachtjäger-Linien teilen."], L["Phase 2: Kabalisten töten, bei Hand der Zerstörung weg. Phase 3 verteilen."] },
			marker = { name = L["Denathrius"], order = { 1, 2, 3 }, note = L["Stern, Kreis, Diamant zeigen die Nachtjäger-Ziele (DBM setzt sie automatisch)."] },
		},
	},
})

Add({ key = "sod", exp = "sl", games = "retail", name = L["Sanktum der Herrschaft"], en = "Sanctum of Domination", de = "Sanktum der Herrschaft", short = "SoD",
	ids = { 2450 }, ji = 1193,
	bosses = {
		{ e = { 2423 }, j = 2435, en = "The Tarragrue", de = "Der Tarragrue",
			text = { L["Der Tarragrue"], "", L["- Überwältigen / Zerschmetterte Rüstung: Tank-Debuff -> Tankwechsel."], L["- Hungernder Nebel: Nebelwand zieht durch den Raum -> Lücke suchen und durchlaufen."], L["- Griff des Todes: Bodeneffekte -> ausweichen."], L["- Ketten der Ewigkeit: markierter Spieler (Stern) wird gefesselt/gezogen -> weg vom Raid."], L["- Überreste vergessener Qualen: Kugeln am Boden -> nach Plan aufsammeln, sie verursachen Schaden je nach Element."], L["- Zorn der Zeitalter: Wut-Buff -> sofort beruhigen (Jäger, Druiden)."], "", L["Taktik: Boss zentral tanken, Nebel geschlossen durch die Lücke, Überreste kontrolliert aufsammeln. Wut sofort beruhigen, ab ca. 10% Burn."] },
			wichtig = L["Wichtig: Zorn der Zeitalter sofort beruhigen (Jäger, Druiden), feste Reihenfolge. Überreste nur nach Plan aufsammeln. Nebel geschlossen durch die Lücke. Ketten-Ziel weg vom Raid. Ab ~10 % Burn mit Kampfrausch."],
			post = { L["TARRAGRUE: Nebel-Lücke suchen! Wut sofort beruhigen."], L["Kettenziel weg vom Raid. Tankwechsel. Überreste nach Plan aufsammeln."] },
			marker = { name = L["Tarragrue"], order = { 1 }, note = L["Stern auf das Ziel von Ketten der Ewigkeit."] },
		},
		{ e = { 2433 }, j = 2442, en = "The Eye of the Jailer", de = "Das Auge des Kerkermeisters",
			text = { L["Das Auge des Kerkermeisters + Todessucher-Augen"], "", L["- Todesverbindung / Durchdringende Linse: schwerer Tankschaden -> Defensive, Tankwechsel."], L["- Hoffnungslose Lethargie und Sich ausbreitendes Elend: Debuffs und Bodenflächen -> rauslaufen, Flächen am Rand ablegen."], L["- Zerstörungsstrahl: markierter Spieler -> Strahl vom Raid weg ausrichten."], L["- Ziehende Ketten: Kette zwischen Spieler und Auge -> nicht durch die Kette laufen, Anweisung folgen."], L["- Phase 2 (Doppelte Sicht): zwei Todessucher-Augen -> gleichmäßig töten, Träge Verderbnis beachten."], L["- Vernichtender Blick: Laser über die Plattform -> rechtzeitig auslaufen."], "", L["Taktik: Phase 1 verteilt um das Auge, Tankwechsel. Phase 2 beide Augen gleichmäßig, Phase 3 Burn, Laser und Flächen ausweichen."] },
			wichtig = L["Wichtig: Tankwechsel nach Plan, Tanks nutzen Defensiven. Strahl-Ziele drehen den Strahl vom Raid weg. Phase 2: beide Augen gleichmäßig töten. Laser rechtzeitig auslaufen. Lethargie-Flächen am Rand ablegen."],
			post = { L["AUGE: Laser ausweichen! Phase 2: beide Augen gleichmäßig!"], L["Elend-Flächen am Rand ablegen. Tankwechsel bei Todesverbindung."] },
		},
		{ e = { 2429 }, j = 2439, en = "The Nine", de = "Die Neun",
			text = { L["Die Neun: Kyra und Signe, dann Skyja + Val'kyr"], "", L["- Kyra - Schwingen des Zorns: zieht Spieler heran -> weglaufen. Unendlicher Schlag: Tank-Stapel -> Tankwechsel."], L["- Formlose Masse: Adds, wirken Vitalität entziehen -> sofort umschalten und unterbrechen."], L["- Signe - Lied der Auflösung / Seelenvoller Stoß: Zauber -> unterbrechen. Widerhallender Refrain: Raidschaden -> Schutz suchen wie zugewiesen."], L["- Ruf der Val'kyr: Val'kyr mit Einzelfähigkeiten -> Agatha-Linie meiden, bei Daschla verteilen, bei Aradne soaken, bei Arthura stacken."], L["- Phase 2 - Skyja: Seele durchbohren (Tankwechsel), Fragmente des Schicksals (weg vom Raid), Essenz verbinden (Defensive)."], "", L["Taktik: Kyra und Signe nah beieinander tanken und beide töten, Formlose Massen sofort. Phase 2: Skyja tanken, Val'kyr-Mechaniken der Reihe nach abarbeiten."] },
			wichtig = L["Wichtig: Formlose Masse: feste Kick-Reihenfolge, sofort umschalten. Signes Zauber kicken. Val'kyr-Mechaniken ansagen: Agatha meiden, Daschla verteilen, Aradne soaken, Arthura stacken. Kyra und Signe gleichmäßig töten."],
			post = { L["DIE NEUN: Schwingen des Zorns -> weglaufen! Formlose Massen töten und kicken!"], L["Signe unterbrechen. Val'kyr-Fähigkeiten beachten. Tankwechsel bei Stapeln."] },
			marker = { name = L["Die Neun"], order = { 8, 7, 6 }, note = L["Totenkopf, Kreuz, Viereck auf die Formlosen Massen; Stern bis Dreieck für Fragmente des Schicksals."] },
		},
		{ e = { 2432 }, j = 2444, en = "Remnant of Ner'zhul", de = "Überrest von Ner'zhul",
			text = { L["Überrest von Ner'zhul + Kugeln der Qual"], "", L["- Kugel der Qual: Kugeln mit Adds/Effekten -> besiegen und von der Plattform werfen."], L["- Böswilligkeit: Debuff (Stern, Kreis, Diamant), explodiert -> an den Rand laufen, weg vom Raid."], L["- Leid: Strahl auf den Tank -> Tank richtet ihn wie geplant aus, sonst niemand davor, Tankwechsel."], L["- Griff der Bosheit: Linien am Boden -> ausweichen."], L["- Zerschmettern: Rüstungsteile fallen ab -> aufnehmen und über die Kante werfen."], "", L["Taktik: Boss nahe der Kante tanken, Kugeln und Rüstungsteile über den Rand werfen, Böswilligkeit geordnet am Rand abarbeiten."] },
			wichtig = L["Wichtig: Böswilligkeit-Ziele laufen an den Rand, nicht in den Raid. Kugeln und Rüstungsteile über die Kante werfen. Leid-Strahl weg vom Raid ausrichten, Tankwechsel. Griff-Linien sofort verlassen."],
			post = { L["NER'ZHUL: Kugeln und Rüstungsteile über den Rand werfen!"], L["Böswilligkeit an den Rand. Nicht vor dem Tank stehen (Leid)."] },
			marker = { name = L["Ner'zhul (Kugeln)"], order = { 7, 6, 5, 4 }, note = L["Kreuz bis Dreieck auf die Kugeln der Qual, nacheinander abarbeiten."] },
		},
		{ e = { 2434 }, j = 2445, en = "Soulrender Dormazain", de = "Seelenfetzer Dormazain",
			text = { L["Seelenfetzer Dormazain + Garrosh Höllschrei"], "", L["- Brandmal der Qual: markierte Spieler (Stern bis Dreieck) -> weg vom Raid, nicht überlappen."], L["- Ruinenklinge: schwerer Tank-Stapel -> Tankwechsel."], L["- Kriegstreiber-Fesseln: Fesseln an Garrosh -> nach Plan umschalten und zerstören."], L["- Peiniger der Schlundgebundenen: Adds wirken Quälender Stachel -> unterbrechen und töten."], L["- Qual und Gequälte Eruptionen: Bodeneffekte -> ausweichen."], L["- Höllschrei: Garrosh bricht aus -> Defensive und Raidheilung."], "", L["Taktik: Boss an fester Position, Adds zuerst, Fesseln in fester Reihenfolge zerstören, Bodeneffekte meiden."] },
			wichtig = L["Wichtig: Peiniger mit fester Kick-Reihenfolge. Fesseln in fester Reihenfolge zerstören. Brandmal-Ziele nicht überlappen. Ruinenklinge: Tankwechsel nach Stapeln. Bei Höllschrei Defensiven und Raid-CDs."],
			post = { L["DORMAZAIN: Adds töten und unterbrechen! Fesseln zerstören!"], L["Brandmal-Ziele weg vom Raid. Tankwechsel bei Ruinenklinge."] },
			marker = { name = L["Dormazain (Adds)"], order = { 8, 7, 6, 5 }, note = L["Totenkopf zuerst: Peiniger in Tötungsreihenfolge, Stern bis Dreieck für Brandmal-Ziele."] },
		},
		{ e = { 2430 }, j = 2443, en = "Painsmith Raznal", de = "Leidensschmied Raznal",
			text = { L["Leidensschmied Raznal"], "", L["- Kreuzförmige Axt, Widerhallender Hammer, Doppelklingige Sense: Waffe trifft den Tank -> Tank läuft raus, danach Tankwechsel."], L["- Stachelbälle: rollen über die Plattform -> Ziel wechseln und zerstören."], L["- Flammenklammer-Falle: Fallen am Boden -> nicht hineinlaufen."], L["- Schattenstahlketten: markierte Spieler (Stern, Kreis, Diamant) -> weg vom Raid, Schaden heilen."], L["- Zwischenphase: Boss verschwindet, Stachelwände ziehen durch -> Lücke suchen und gemeinsam durch."], "", L["Taktik: Boss mittig tanken, Tankwechsel nach jeder Waffenfähigkeit. Bälle zügig töten, Fallen meiden, in der Zwischenphase durch die Lücken."] },
			wichtig = L["Wichtig: Nach jeder Waffenfähigkeit Tankwechsel. Stachelbälle zügig zerstören. Fallen meiden. Ketten-Ziele weg vom Raid. Zwischenphase: Lücke in den Stachelwänden gemeinsam suchen, nie zurückbleiben."],
			post = { L["RAZNAL: Stachelbälle zerstören! Fallen meiden!"], L["Tankwechsel nach jeder Waffe. Zwischenphase: Lücke in den Wänden suchen."] },
			marker = { name = L["Raznal"], order = { 1, 2, 3 }, note = L["Stern, Kreis, Diamant zeigen die Ziele der Schattenstahlketten."] },
		},
		{ e = { 2436 }, j = 2446, en = "Guardian of the First Ones", de = "Wächter der Ersten",
			text = { L["Wächter der Ersten + Energiekerne"], "", L["- Energiekerne: Kerne liefern dem Boss Energie und bilden eine Schutzzone -> Boss bei Bedarf an einen Kern führen."], L["- Säuberungsprotokoll / Strahlende Energie: Raidschaden -> in die Schutzzone eines Kerns gehen."], L["- Kernschmelze: Kern explodiert -> rechtzeitig rauslaufen."], L["- Bedrohungsneutralisierung: markierte Spieler (Stern, Kreis, Diamant) -> weg vom Raid, verteilen."], L["- Zerfall: Strahl in Linie -> außerhalb der Linie stehen."], L["- Zerschmettern / Auslöschen: Tank-Debuff -> Defensive, Tankwechsel."], "", L["Taktik: Boss in die Nähe eines Kerns tanken, Raid bei Säuberungsprotokoll in die Schutzzone, vor Kernschmelze raus. Tankwechsel nach Plan."] },
			wichtig = L["Wichtig: Boss rechtzeitig zu einem Kern führen. Bei Säuberungsprotokoll alle in die Schutzzone, vor Kernschmelze raus. Bedrohungsneutralisierung: Ziele verteilen. Zerfall-Linie meiden. Tankwechsel nach Plan."],
			post = { L["WÄCHTER: Bei Protokoll in die Kern-Zone! Bei Kernschmelze raus!"], L["Neutralisierung weg vom Raid. Zerfall-Linie meiden. Tankwechsel."] },
			marker = { name = L["Wächter der Ersten"], order = { 1, 2, 3 }, note = L["Stern, Kreis, Diamant zeigen die Ziele der Bedrohungsneutralisierung."] },
		},
		{ e = { 2431 }, j = 2447, en = "Fatescribe Roh-Kalo", de = "Schicksalsschreiber Roh-Kalo",
			text = { L["Schicksalsschreiber Roh-Kalo"], "", L["- Schicksalhafte Verbindung: Strahlen über die Plattform -> ausweichen."], L["- Ruf der Ewigkeit: markierte Spieler explodieren -> rauslaufen, verteilen."], L["- Schicksal beschwören: Tank-Debuff, beim Ablaufen erscheint ein Schatten -> Tankwechsel, Schatten töten, verfolgter Spieler rennt."], L["- Phase 2 - Schicksal neu ausrichten: Runenringe -> zugewiesene Spieler drehen die Ringe in Position."], L["- Verzweiflung (Monstrositäten): Adds wirken -> unterbrechen und töten."], "", L["Taktik: Phase 1 verteilt, Strahlen ausweichen, Schatten zügig töten. Phase 2 Ringe ausrichten und Adds kontrollieren, danach Burn."] },
			wichtig = L["Wichtig: Ring-Dreher in Phase 2 fest benennen, Rest schützt sie. Monstrositäten: feste Kick-Reihenfolge. Schatten zügig töten, verfolgter Spieler rennt. Ruf-der-Ewigkeit-Ziele raus. Strahlen ausweichen."],
			post = { L["ROH-KALO: Strahlen ausweichen! Ruf der Ewigkeit -> rauslaufen!"], L["Phase 2: Runen ausrichten. Monstrositäten unterbrechen."] },
			marker = { name = L["Roh-Kalo"], order = { 8, 7 }, note = L["Totenkopf und Kreuz auf die Monstrositäten (DBM)."] },
		},
		{ e = { 2422 }, j = 2440, en = "Kel'Thuzad", de = "Kel'Thuzad",
			text = { L["Kel'Thuzad + Phylakterium"], "", L["- Frostschlag: markiertes Ziel -> mit mehreren Spielern stacken und teilen."], L["- Heulender Blizzard / Gletscherwinde: Bodeneffekte -> ausweichen."], L["- Glazialer Zorn: Eisspitzen an Spielern -> wegstellen, Spitzen zerstören."], L["- Echo des Vergessens: markierte Spieler -> rauslaufen und Fläche am Rand ablegen."], L["- Seelenbruch / Seelenerschöpfung: Tankschaden, Seelensplitter im Phylakterium -> Tankwechsel, Splitter töten."], L["- Phase 2 (Phylakterium): Teil des Raids geht hinein -> Überrest bekämpfen, Rest hält Adds draußen."], "", L["Taktik: Phase 1 Boss tanken, Flächen am Rand ablegen. Phase 2 feste Gruppe ins Phylakterium, Rest kontrolliert Adds. Phase 3 Burn."] },
			wichtig = L["Wichtig: Phylakterium-Gruppe vorher fest einteilen. Frostschlag immer mit mehreren Spielern teilen. Echo-Flächen am Rand ablegen. Seelenbruch: Tankwechsel, Splitter töten. Eisspitzen zerstören, Adds draußen halten."],
			post = { L["KEL'THUZAD: Frostschlag gemeinsam teilen! Phylakterium-Gruppe bereit!"], L["Echo des Vergessens am Rand ablegen. Blizzard ausweichen. Tankwechsel."] },
			marker = { name = L["Kel'Thuzad (Adds)"], order = { 8, 7, 6, 5, 4 }, note = L["Symbole auf Seelensplitter bzw. Seelenschnitter in Tötungsreihenfolge."] },
		},
		{ e = { 2435 }, j = 2441, en = "Sylvanas Windrunner", de = "Sylvanas Windläufer",
			text = { L["Sylvanas Windläufer"], "", L["- Herrschaftsketten: Ketten greifen Spieler -> Ketten zerstören, Bodenpfeilen ausweichen."], L["- Wehklagender Pfeil: markiertes Ziel -> rauslaufen, Tankwechsel nach Pfeil auf den Tank."], L["- Schattendolch / Schleier der Dunkelheit: Debuff und Bodeneffekte -> heilen, ausweichen."], L["- Zwischenphase: Sylvanas zerstört die Plattform -> der Bridge-Taktik folgen, Ruin unterbrechen."], L["- Phase 2: Bansheeklage (verteilen), Spukwelle (ausweichen), Adds auf den Brücken -> unterbrechen und töten."], L["- Phase 3 (Oribos): Bansheefluch (bannen), Bansheeschrei (verteilen), Zerstören (wegrennen)."], "", L["Taktik: Phase 1 zentral, Ketten sofort zerstören. Zwischenphase den Brücken folgen, Phase 2 Adds kontrollieren, Phase 3 verteilt auf den Plattformen."], L["Letzter Boss des Sanktums der Herrschaft."] },
			wichtig = L["Wichtig: Ketten sofort zerstören, Bodenpfeilen ausweichen. Wehklagender Pfeil: Ziel raus, Tankwechsel. Zwischenphase: Brücken-Taktik folgen, Ruin unterbrechen. Phase 3: Bansheefluch bannen, verteilt stehen."],
			post = { L["SYLVANAS: Ketten zerstören! Pfeil-Ziel rauslaufen!"], L["Ruin unterbrechen. Phase 3: verteilen, Bansheefluch bannen."] },
			marker = { name = L["Sylvanas"], order = { 1, 2, 3 }, note = L["Stern, Kreis, Diamant zeigen die Ziele von Wehklagender Pfeil."] },
		},
	},
})

Add({ key = "sfo", exp = "sl", games = "retail", name = L["Mausoleum der Ersten"], en = "Sepulcher of the First Ones", de = "Mausoleum der Ersten", short = "SotFO",
	ids = { 2481 }, ji = 1195,
	bosses = {
		{ e = { 2512 }, j = 2458, en = "Vigilant Guardian", de = "Aufmerksamer Wächter",
