			post = { L["WÄCHTER: Bei Exponierter Kern SCHUTZ SUCHEN! Adds töten!"], L["Tankwechsel. Materieauflösung rauslaufen, Laser ausweichen."] },
		},
		{ e = { 2542 }, j = 2465, en = "Skolex, the Insatiable Ravener", de = "Skolex, der unersättliche Räuber",
			text = { L["Skolex, der unersättliche Räuber"], "", L["- Staubschlag: Raidschaden mit Stapel -> Heiler planen Cooldowns."], L["- Würgen: frontaler Kegel -> rausgehen."], L["- Rachen der Risse / Zerfetzen: Tank-Debuff -> Tankwechsel."], L["- Verschlingendes Graben: Boss gräbt sich ein -> Bodeneffekten ausweichen."], L["- Ewigkeits-Overdrive: Wut bei voller Energie -> Boss vorher töten."], "", L["Taktik: Boss mittig tanken, Kegel ausweichen, Tankwechsel nach Absprache. DPS-Check vor Overdrive."] },
			wichtig = L["Wichtig: DPS-Check: Boss vor Ewigkeits-Overdrive töten – Kampfrausch und Tränke planen. Würgen-Kegel meiden. Tankwechsel nach Absprache. Heiler-CDs gegen steigenden Staubschlag rotieren."],
			post = { L["SKOLEX: Würgen ausweichen! Tankwechsel bei Rachen!"], L["Staubschlag mit Cooldowns heilen. Graben ausweichen."] },
		},
		{ e = { 2553 }, j = 2470, en = "Artificer Xy'mox", de = "Konstrukteur Xy'mox",
			text = { L["Konstrukteur Xy'mox"], "", L["- Dimensionsriss: zwei markierte Spieler (Stern, Kreis) erzeugen Wurmlöcher -> weit auseinander ablegen."], L["- Vorläuferringe: Ringe expandieren -> durch die Lücke laufen."], L["- Glyphe der Umsiedlung: Tank-Debuff -> Tank läuft weg vom Raid, Tankwechsel."], L["- Stasisfalle: Fallen am Boden -> nicht hineinlaufen."], L["- Hyperlichtfunke / Kartell-Elite: Raidschaden und Adds -> heilen, Adds töten und unterbrechen."], L["- Massive Explosion: schwerer Tankschlag -> Defensive, Tankwechsel."], "", L["Taktik: Wurmlöcher weit auseinander setzen, Ringe durch die Lücken, Adds zuerst. Tankwechsel nach Glyphe und Explosion."] },
			wichtig = L["Wichtig: Wurmlöcher weit auseinander setzen, Träger sagen Position an. Ringe durch die Lücken. Glyphe-Tank weit raus, Tankwechsel nach Glyphe und Explosion. Kartell-Elite: Adds kicken und zuerst töten."],
