			text = { L["Dausegne, das gefallene Orakel"], "", L["- Zerfallshalo: Ringe breiten sich aus -> durch die Lücken laufen."], L["- Taumelndes Sperrfeuer: markierte Spieler -> Schaden mit Mitspielern teilen."], L["- Vernichtungsbogen: Kegel -> ausweichen."], L["- Erfüllte Schläge: Tank-Stapel -> Tankwechsel."], L["- Herrschaftskern: Adds wirken Herrschaftsbolzen -> unterbrechen und töten."], "", L["Taktik: Boss mittig, Ringe geordnet durchqueren, Sperrfeuer gemeinsam tragen, Kern-Adds zügig töten."] },
			wichtig = L["Wichtig: Herrschaftsbolzen der Kern-Adds mit fester Kick-Reihenfolge. Sperrfeuer mit mehreren Spielern tragen. Ringe geordnet durchqueren. Tankwechsel nach Stapeln. Vernichtungsbogen ausweichen."],
