		{ e = { 2539 }, j = 2461, en = "Lihuvim, Principal Architect", de = "Lihuvim, der oberste Architekt",
			text = { L["Lihuvim, der oberste Architekt + Automa"], "", L["- Harmonische / Melodische Ausrichtung: Raid in zwei Gruppen -> Gruppen nach Debuff zusammenstellen."], L["- Protoformkaskade: frontaler Angriff -> ausweichen."], L["- Instabiles Partikel: markierte Spieler -> nicht in andere Spieler laufen."], L["- Dekonstruierende Energie: markierte Spieler (Stern, Kreis) -> rauslaufen."], L["- Automa (Form der Wache): Adds -> töten."], L["- Resonanz: Tank -> Tankwechsel."], "", L["Taktik: Boss mittig, Adds zuerst, Kaskade meiden, Ausrichtung sauber in Gruppen."] },
			wichtig = L["Wichtig: Gruppen nach Ausrichtung vorher festlegen. Instabile-Partikel-Ziele nicht in andere laufen. Automa-Adds zuerst. Kaskade ausweichen. Dekonstruierende-Energie-Ziele raus. Tankwechsel nach Resonanz."],
