			text = { L["Halondrus der Rückgewinner"], "", L["- Erdbrecher-Raketen: Einschläge auf Spieler -> verteilen."], L["- Flüchtige Ladungen: Bomben an markierten Spielern -> vom Raid weg ablegen, nicht in Gruppen explodieren lassen."], L["- Seismische Erschütterungen / Zerschmettern: Bodeneffekte -> ausweichen."], L["- Planetenbrecher-Strahl: Strahl über die Plattform -> aus der Linie gehen."], L["- Lichtsplitter-Strahl: Tankschaden -> Defensive, Tankwechsel."], L["- Rückgewinnen: Boss baut einen Schild auf -> Schild zügig brechen."], "", L["Taktik: Raid verteilt hinter dem Boss, Bomben abseits ablegen, Strahlen meiden. In Phase 2 (Umsiedlungsform) zieht der Boss weiter -> geschlossen mitbewegen."] },
			wichtig = L["Wichtig: Flüchtige Ladungen einzeln abseits ablegen. Bei Raketen verteilt stehen. Strahlen meiden. Tankwechsel nach Lichtsplitter. Schild zügig brechen. Phase 2: Raid geschlossen mit dem Boss bewegen."],
