			wichtig = L["Wichtig: Kingsmourne-Gruppe fest einteilen. Blasphemie-Partner (Übermut/Hoffnungslosigkeit) sofort zusammen. Barriere gemeinsam auflösen. Spiegelbilder: feste Kick-Reihenfolge. Bösen Stern raus."],
			post = { L["ANDUIN: Kingsmourne-Seelen befreien! Blasphemie-Partner suchen!"], L["Böser Stern rauslaufen. Spiegelbilder unterbrechen."] },
