			text = { L["Lords des Schreckens: Mal'Ganis und Kin'tessa"], "", L["- Ins Dunkle (Mal'Ganis): Raum wird verdunkelt, Manifestierte Schatten erscheinen -> Schatten töten, Gefräßiger Hunger unterbrechen."], L["- Eindringen des Schreckens (Kin'tessa): Raid in Rollen -> Verräter in den eigenen Reihen finden und angreifen."], L["- Aaswolke / Verfallsschwarm: Debuff und Raidschaden -> verteilen, Schaden wie angesagt teilen."], L["- Ängstliches Zittern: Debuff (Stern, Kreis) -> rauslaufen, Furcht wird beim Bannen übertragen."], L["- Platzender Schrecken / Verstörende Träume: Debuffs -> bannen."], L["- Quälender Schlag / Saugende Klauen: Tank-Stapel -> Tankwechsel."], "", L["Taktik: Beide Lords nah beieinander tanken und gleichmäßig schaden. In den Sonderphasen Schatten-Adds bzw. Verräter-Minispiel zuerst lösen."] },
			wichtig = L["Wichtig: Beide Lords gleichmäßig schaden. Ängstliches Zittern: Bannen nur, wenn Raid weit weg, sonst springt Furcht. Bei Ins Dunkle Schatten töten und Hunger kicken. Verräter-Minispiel zuerst lösen. Tankwechsel nach Stapeln."],
