			text = { L["Rygelon"], "", L["- Himmelszusammenbruch: Quasare/Kerne erscheinen -> nach Plan töten, Explosion beachten."], L["- Dunkle Finsternis: markierte Spieler (Stern, Kreis, Diamant) -> rauslaufen."], L["- Dunkler Quasar: persönlicher Debuff -> weg vom Raid."], L["- Massiver Knall: tödlicher Raidschaden -> rechtzeitig in Sicherheit (Schutz nach Plan)."], L["- Ereignishorizont / Kosmische Unregelmäßigkeit: Debuff und Tank-Stapel -> verteilen, Tankwechsel."], L["- Gravitationskollaps: Soak -> Tanks fangen ab."], "", L["Taktik: Raid verteilt, Quasare kontrolliert töten, Dunkle Finsternis rauslaufen. Vor Massiver Knall gemeinsam in Sicherheit."] },
			wichtig = L["Wichtig: Vor Massivem Knall rechtzeitig in Sicherheit – häufigste Wipe-Ursache. Quasare nach Plan töten. Finsternis-Ziele raus. Gravitationskollaps: Tanks fangen ab. Tankwechsel nach Stapeln."],
			post = { L["RYGELON: Quasare töten! Massiver Knall -> in Sicherheit!"], L["Finsternis rauslaufen. Tankwechsel bei Stapeln."] },
			marker = { name = L["Rygelon"], order = { 1, 2, 3 }, note = L["Stern, Kreis, Diamant zeigen die Ziele der Dunklen Finsternis."] },
		},
		{ e = { 2537 }, j = 2464, en = "The Jailer", de = "Der Kerkermeister",
			text = { L["Der Kerkermeister"], "", L["- Rune der Verdammnis: markierte Spieler (Stern bis Mond) -> nach Plan in die Grube springen."], L["- Rune der Herrschaft: Soak-Kreise -> gemeinsam abdecken."], L["- Ketten der Unterdrückung: zieht Spieler zum Boss -> dagegen weglaufen."], L["- Martyrium / Elend: Tankschaden -> Defensive, Tankwechsel."], L["- Dezimator: Linienangriff -> aus der Linie gehen."], L["- Entweihen / Verwüstung: Bodeneffekte und Soak -> rauslaufen bzw. teilen."], "", L["Taktik: Raid nach Plan auf der Plattform, Runen geordnet abarbeiten, Tankwechsel. In späteren Phasen Azeroth-Mechaniken (Weltenzerstörer) laut Plan."], L["Letzter Boss von Shadowlands."] },
			wichtig = L["Wichtig: Runen der Verdammnis nach Plan in die Grube. Herrschafts-Kreise immer soaken. Ketten: dagegen weglaufen. Tankwechsel nach Plan. Dezimator-Linie meiden. Kampfrausch und Raid-CDs für die Endphase."],
			post = { L["KERKERMEISTER: Runen nach Plan! Bei Ketten weglaufen!"], L["Tankwechsel. Dezimator-Linie meiden."] },
			marker = { name = L["Kerkermeister"], order = { 1, 2, 3, 4, 5, 6 }, note = L["Stern bis Mond auf die Ziele der Rune der Verdammnis."] },
		},
	},
})

