		{ e = { 2688 }, j = 2522, en = "Kazzara, the Hellforged", de = "Kazzara die Höllengeschmiedete",
			text = { L["Kazzara die Höllengeschmiedete"], "", L["- Schreckensrisse: markierte Spieler hinterlassen Risse am Boden -> am Raumrand ablegen, nicht im Raid."], L["- Strahlen der Qual: Strahlen, die durch den Raum ziehen -> Lücken suchen und ausweichen."], L["- Höllenstahlsplitter: Splitter fliegen nach außen und hinterlassen Flächen -> verteilen und ausweichen."], L["- Terrorklauen: Tankdebuff mit Stapeln -> Tankwechsel nach Ansage."], L["- Höllenstrahl bei 80/60/40%: Kazzara verliert ein Höllenherz und erhält neue Fähigkeiten -> Raid-CDs einplanen."], "", L["Taktik: Boss mittig tanken, Risse kontrolliert am Rand stapeln, damit genug Platz bleibt; je weniger Herzen, desto mehr Fähigkeiten gleichzeitig."] },
			wichtig = L["Wichtig: Risse von Anfang an eng an EINER Randstelle stapeln, sonst fehlt nach den Herzphasen der Platz. Lücken in den Strahlen ansagen. Heldentum und Raid-CDs meist für die letzte Herzphase aufsparen."],
			post = { L["KAZZARA: Risse am Rand ablegen, Strahlen ausweichen!"], L["Tankwechsel bei Terrorklauen. Raid-CDs bei den Herz-Übergängen."] },
		},
		{ e = { 2687 }, j = 2529, en = "The Amalgamation Chamber", de = "Die Verschmelzungskammer",
			text = { L["Die Verschmelzungskammer: Essenz der Schatten + Ewige Lohe (danach Schattenflammenverschmelzung)"], "", L["- Nähe der Bosse: stehen sie zu dicht beieinander, verstärken sie sich gegenseitig -> beide Bosse getrennt tanken."], L["- Schattenseite: Schattenschaden-Debuffs und Detonationen -> markierte Spieler laufen aus dem Raid."], L["- Feuerseite: Meteore und Feuerflächen -> Meteore mit mehreren Spielern soaken, Flächen ausweichen."], L["- Phase 2 (beide bei 50%): Bosse verschmelzen zur Schattenflammenverschmelzung -> Raid-CDs, Stapel-Mechaniken gemeinsam nehmen."], "", L["Taktik: Raid in zwei Gruppen aufteilen, beide Bosse gleichmäßig auf 50% bringen und weit getrennt halten; danach gemeinsam auf den verschmolzenen Boss."] },
			wichtig = L["Wichtig: Leben beider Bosse ständig vergleichen, läuft einer vor, DDs umverteilen. Meteore nie allein, Schatten-Debuffträger sofort raus. Tanks lassen die Bosse nie zusammenkommen. Heldentum auf die Verschmelzung."],
			post = { L["VERSCHMELZUNGSKAMMER: Bosse getrennt halten, gleichmäßig auf 50% bringen!"], L["Phase 2: Verschmelzung – Raid-CDs, Soaks gemeinsam nehmen."] },
			marker = { name = L["Verschmelzungskammer"], order = { 8, 7 }, note = L["Totenkopf auf Essenz der Schatten, Kreuz auf Ewige Lohe."] },
		},
		{ e = { 2693 }, j = 2530, en = "The Forgotten Experiments", de = "Die vergessenen Experimente",
			text = { L["Die vergessenen Experimente: Neldris, Thadrion, Rionthus"], "", L["- Neldris: Ansturm und Schläge auf Spieler -> Laufwege freihalten, getroffene Spieler heilen."], L["- Thadrion: instabile Essenz auf Spielern -> markierte Spieler aus dem Raid laufen, Explosion nicht in der Gruppe."], L["- Rionthus: Tiefenatem über einen Teil der Plattform -> Atemweg sofort verlassen."], L["- Die Experimente werden nacheinander aktiv -> Fähigkeiten überlagern sich, Raid-CDs auf Überschneidungen."], "", L["Taktik: Aktiven Drachen tanken, Schaden auf die aktiven Ziele bündeln und Flächen am Rand platzieren; Fernkampf verteilt, Nahkampf hinter den Bossen."] },
			wichtig = L["Wichtig: Fokusziel nach Ansage, Cleave auf aktive Drachen nutzen. Essenz-Träger weit weg vom Raid, Atemseite sofort räumen. Typischer Wipe: Überschneidungen ohne Raid-CDs – Heiler-CDs vorher einteilen."],
			post = { L["VERGESSENE EXPERIMENTE: Atem ausweichen, Debuffs raus aus dem Raid!"], L["Schaden auf aktive Drachen. Raid-CDs bei Überschneidungen."] },
			marker = { name = L["Vergessene Experimente"], order = { 8, 7, 6 }, note = L["Totenkopf Neldris, Kreuz Thadrion, Viereck Rionthus."] },
		},
		{ e = { 2682 }, j = 2524, en = "Assault of the Zaqali", de = "Angriff der Zaqali",
			text = { L["Angriff der Zaqali: Kriegsherr Kagni + Zaqali-Angreifer"], "", L["- Leitern/Mauern: Zaqali-Adds klettern über die Mauern -> eine Gruppe geht nach oben und tötet sie dort."], L["- Große Adds (Champions/Rufer): hoher Schaden oder Zauber -> tanken, wichtige Zauber unterbrechen."], L["- Boss-Feuerflächen und Fallen auf dem Wall -> ausweichen, nicht im Feuer stehen."], L["- Phase 2: Kagni stürmt die Mauer -> Raid sammelt sich oben, Raid-CDs für den Endspurt."], "", L["Taktik: Raid in zwei Teams (oben/unten) aufteilen, Adds auf beiden Seiten kontrollieren und Kagni dabei gleichmäßig runterbringen."] },
			wichtig = L["Wichtig: Teams oben/unten vor dem Pull fest einteilen, jedes mit Tank, Heiler und Kickern. Kein Add darf über die Mauer durchkommen. Zauber-Adds mit fester Kick-Rotation. Heldentum für Phase 2 mit allen oben."],
			post = { L["ZAQALI: Team oben räumt Adds, Team unten auf den Boss!"], L["Wichtige Zauber unterbrechen. Phase 2: alle zusammen, Raid-CDs."] },
			marker = { name = L["Zaqali"], order = { 8, 7, 6 }, note = L["Totenkopf und Kreuz auf große Adds, Viereck auf das nächste Zauber-Add zum Unterbrechen."] },
		},
		{ e = { 2680 }, j = 2525, en = "Rashok, the Elder", de = "Rashok der Älteste",
			text = { L["Rashok der Älteste"], "", L["- Geladener Schmetterschlag: großer Soak-Kreis -> der ganze Raid stellt sich hinein und teilt den Schaden."], L["- Schattenlavastoß: frontaler Kegel -> nicht vor dem Boss stehen."], L["- Flammen der Verdammnis: Soaks/Flächen auf Spielern -> gemäß Einteilung soaken, Rest weg."], L["- Unnachgiebige Wut: an den Leitungen lädt sich Rashok auf -> Boss vom Leiter wegziehen bzw. Phase mit Raid-CDs überstehen."], "", L["Taktik: Boss mittig tanken, Soaks gemeinsam nehmen und Kegel im Blick behalten; bei Energiephasen Positionierung nach Ansage."] },
			wichtig = L["Wichtig: Schmetterschlag: möglichst ALLE rein, fehlende Soaker kosten den Raid. Frontkegel nie Richtung Raid drehen. Positionierung an den Leitungen nur nach Ansage. Heiler-CDs auf die Wutphase rotieren."],
			post = { L["RASHOK: Schmetterschlag ALLE soaken, nicht vor den Boss!"], L["Flammen nach Einteilung soaken. Raid-CDs bei Wutphase."] },
		},
		{ e = { 2689 }, j = 2532, en = "The Vigilant Steward, Zskarn", de = "Der wachsame Verwalter Zskarn",
			text = { L["Der wachsame Verwalter Zskarn + Golems"], "", L["- Drachenfeuerfallen: gefährliche Feuerfallen am Boden -> ausweichen bzw. gemäß Ansage auslösen/entschärfen."], L["- Belebte Golems: Adds -> tanken und töten; je nach Mechanik in Fallen ziehen."], L["- Schrapnellbombe: Bombe muss gesoakt werden -> mehrere Spieler soaken gleichzeitig."], L["- Taktische Zerstörung: Drachenköpfe schießen Feuer über den Boden -> Linien ausweichen."], L["- Tankdebuff mit Stapeln -> Tankwechsel."], "", L["Taktik: Boss zentral, Adds zügig töten und Bomben sofort soaken; Fallen und Linien ständig im Blick behalten."] },
			wichtig = L["Wichtig: Mechaniken vor DPS: Bomben nie unbesetzt, feste Soak-Gruppen. Fallen nur nach Ansage auslösen/entschärfen, sonst wird der Raum zu. Golems nicht stehen lassen. Tankwechsel nach Ansage strikt einhalten."],
			post = { L["ZSKARN: Bomben soaken, Feuerlinien und Fallen ausweichen!"], L["Golems zügig töten. Tankwechsel nach Ansage."] },
			marker = { name = L["Zskarn"], order = { 8, 7 }, note = L["Totenkopf und Kreuz auf die Golems."] },
		},
		{ e = { 2683 }, j = 2527, en = "Magmorax", de = "Magmorax",
			text = { L["Magmorax"], "", L["- Geschmolzene Spucke: Spieler werden getroffen und hinterlassen Magmapfützen -> Pfützen am Rand ablegen."], L["- Magmapfützen wachsen -> Tanks/Spieler soaken Pfützen nach Ansage, damit Platz bleibt."], L["- Entzündendes Brüllen: Raidschaden, verstärkt durch Pfützen -> Raid-CDs, Heiler bereit."], L["- Lodernder Atem: frontaler Feuerkegel -> nicht vor dem Boss stehen."], L["- Bei voller Energie: Katastrophaler Ausbruch -> Raid-CD, Boss vorher in neuen Bereich bringen."], "", L["Taktik: Magmorax im Kreis durch den Raum ziehen, Pfützen kontrolliert ablegen und abbauen; Raid-CDs auf Brüllen und Ausbruch."] },
			wichtig = L["Wichtig: Pfützen-Ablage vorher planen (im Kreis), Boss mitziehen. Wächst der Raum zu, steigt der Brüllen-Schaden stark – Pfützen-Abbau nach Ansage hat Vorrang. Heiler-CDs fest auf Brüllen und Ausbruch rotieren."],
			post = { L["MAGMORAX: Pfützen am Rand ablegen, nicht vor den Boss!"], L["Boss im Kreis ziehen. Raid-CDs bei Brüllen/Ausbruch."] },
		},
		{ e = { 2684 }, j = 2523, en = "Echo of Neltharion", de = "Echo von Neltharion",
			text = { L["Echo von Neltharion"], "", L["- Verdrehte Erde: Steinwände entstehen -> Wände nutzen bzw. gezielt mit Fähigkeiten zerstören."], L["- Hereinbrechende Dunkelheit: Linien-Ansturm auf Spieler -> durch die richtige Wand laufen lassen, Raid nicht im Weg."], L["- Echoende Spalte: Raidschaden -> Raid-CDs."], L["- Phase 2: Realitätsriss und Verderbnis -> Leerenzonen nach Ansage schließen, Debuffs beachten."], L["- Phase 3: hoher Raidschaden, Schläge auf Tanks -> Tankwechsel, Raid-CDs."], "", L["Taktik: Positionierung zu den Wänden ist entscheidend; Ansturm-Ziele führen die Linien kontrolliert, Rest steht dahinter gestapelt."] },
			wichtig = L["Wichtig: Wände nicht unnötig zerstören, sie sind Deckung. Ansturm-Ziele laufen bewusst durch die Wände, Rest gestapelt dahinter. Risse in Phase 2 nur von eingeteilten Spielern schließen. Heldentum meist Phase 3."],
			post = { L["NELTHARION: Ansturm durch die Wände führen, Raid aus dem Weg!"], L["Phase 2: Risse nach Ansage. Raid-CDs auf Spalten."] },
		},
		{ e = { 2685 }, j = 2520, en = "Scalecommander Sarkareth", de = "Schuppenkommandant Sarkareth",
			text = { L["Schuppenkommandant Sarkareth"], "", L["- Phase 1: Versengende Bombe -> mehrere Spieler soaken; treibende Glut ausweichen."], L["- Unterdrückendes Heulen: Debuff/Furcht -> bannen bzw. Debuffs nach Ansage entfernen."], L["- Phase 2 (Leere): Leerebomben und Bodenflächen -> verteilen, Flächen nicht in den Raid legen."], L["- Phase 3: Leere-Plattform mit dauerhaftem Raidschaden -> Raid-CDs, Debuffs sauber spielen."], L["- Tankdebuffs in jeder Phase -> Tankwechsel."], "", L["Taktik: Drei Phasen, steigender Raidschaden; Soaks gemeinsam nehmen und Flächen sauber am Rand platzieren. Letzter Boss von Aberrus."] },
			wichtig = L["Wichtig: Bomben nie allein soaken. Leere-Flächen strikt an den Rand, Laufwege freihalten. Tankwechsel in jeder Phase nach Ansage. Raidschaden steigt stetig: Raid-CDs und Heldentum für Phase 3 aufsparen."],
			post = { L["SARKARETH: Bomben soaken, Leere-Flächen raus aus dem Raid!"], L["Tankwechsel nach Ansage. Raid-CDs in Phase 3."] },
		},
	},
})

Add({ key = "ami", exp = "df", games = "retail", name = L["Amirdrassil, die Hoffnung des Traums"], en = "Amirdrassil, the Dream's Hope", de = "Amirdrassil, die Hoffnung des Traums", short = "Amirdrassil",
