			wichtig = L["Wichtig: Feuerwachstum erst bannen, wenn der Spieler aus dem Raid ist. Wurzeln (Massenumklammerung) schnell freibannen/befreien. Soak-Kreise fest zuteilen. Beim Plattformflug Ringe/Federn mitnehmen, nicht abstürzen."],
			post = { L["TINDRAL: Debuffs kontrolliert bannen, Sterne soaken!"], L["Zwischenphase: Flugweg folgen, Federn sammeln."] },
