			text = { L["Fyrakk der Lodernde"], "", L["- Phase 1: Flammendes Leiden/Feuer-Debuffs und Wildfeuer -> verteilen, Flächen am Rand."], L["- Zwischenphase: Fyrakk korrumpiert den Traum, Samen/Kugeln -> Kugeln nach Ansage einsammeln, Adds töten."], L["- Phase 2: Schattenflammen-Fähigkeiten und Adds -> Adds töten, wichtige Zauber unterbrechen."], L["- Phase 3: sehr hoher Raidschaden und Soak-Mechaniken -> Raid-CDs stapeln, Soaks zuweisen."], L["- Tankschläge mit Stapeln -> Tankwechsel."], "", L["Taktik: Drei Phasen mit Zwischenphasen; Flächen kontrolliert platzieren und Raid-CDs für Phase 3 sparen."], L["Beute: legendäre Zweihandaxt Fyr'alath (Fyr'alath the Dreamrender)."] },
