	bosses = {
		{ e = { 2902 }, j = 2607, en = "Ulgrax the Devourer", de = "Ulgrax der Verschlinger",
			text = { L["Ulgrax der Verschlinger + Wuselnder Schwarm (Adds)"], "", L["- Tankkombo (Brutales Zerschmettern / Peitschen): stapelnder Schaden -> Tankwechsel nach jeder Kombo, Defensiv-CDs."], L["- Giftpeitsche: Gift-DoT auf mehreren Spielern -> heilen, betroffene Spieler verteilen."], L["- Netze der Pirscher: Netze auf dem Boden fesseln Spieler -> nicht hineinlaufen, Netze am Rand ablegen."], L["- Fleischfressender Wettstreit: markierter Spieler wird zum Boss gezogen -> Raid stellt sich dazu und teilt den Schaden."], L["- Phase 2 (Hungriges Gebrüll): steigender Raidschaden, Juggernaut-Ansturm -> Ansturm ausweichen, Fleischbrocken aufnehmen und an Ulgrax verfüttern."], "", L["Taktik: Phase 1 Boss am Rand tanken, Netze und Adds kontrollieren; in Phase 2 Brocken schnell verfüttern, damit er zurück in Phase 1 geht."] },
			wichtig = L["Wichtig: Phase 2: Fleischbrocken sofort zu Ulgrax tragen – je länger, desto mehr Raidschaden. Tankwechsel nach jeder Kombo strikt. Netze am Rand, nie in Laufwege. Juggernaut-Ansturm ausweichen geht vor DPS."],
			post = { L["ULGRAX: Netze an den Rand, gezogenen Spieler gemeinsam stützen!"], L["Phase 2: Ansturm ausweichen, Fleischbrocken verfüttern. Tankwechsel nach Kombo."] },
		},
		{ e = { 2917 }, j = 2611, en = "The Bloodbound Horror", de = "Der blutgebundene Schrecken",
			text = { L["Der blutgebundene Schrecken + Vergessene Vorboten, Verlorene Wächter (Schattenreich)"], "", L["- Grausiges Erbrechen: Kegel schickt getroffene Spieler ins Schattenreich -> feste Gruppe nimmt ihn, tötet dort die Adds."], L["- Vergessene Vorboten: wirken Schwarzes Bollwerk -> immer unterbrechen, Wächter vom Tank im Reich halten."], L["- Blutspeiendes Bluten: Linien/Strudel auf Spielern -> ausweichen, nicht durch den Raid ziehen."], L["- Blutspritzer: riesiger Raidschaden, nach Entfernung reduziert -> rechtzeitig weit weg vom Boss."], L["- Griff aus dem Jenseits / Purpurregen: Tentakel töten bzw. ausweichen, Regen-DoT mit Heiler-CDs abfangen."], "", L["Taktik: Zwei Gruppen im Wechsel für das Schattenreich einteilen, Kicks auf den Vorboten fest zuweisen; Hauptraid bleibt beim Boss und weicht Flächen aus."] },
			wichtig = L["Wichtig: Kick-Rotation auf Schwarzes Bollwerk fest zuweisen, kein Cast darf durchgehen. Reichsgruppen fest im Wechsel, nicht doppelt hinein. Bei Blutspritzer alle rechtzeitig weit weg. Heiler-CDs auf Purpurregen."],
			post = { L["SCHRECKEN: Vorboten im Schattenreich immer kicken!"], L["Erbrechen nur die eingeteilte Gruppe. Bei Blutspritzer weit weg vom Boss!"] },
			marker = { name = L["Blutgebundener Schrecken"], order = { 8, 7 }, note = L["Totenkopf und Kreuz auf die Vergessenen Vorboten im Schattenreich für feste Kicks."] },
		},
		{ e = { 2898 }, j = 2599, en = "Sikran, Captain of the Sureki", de = "Sikran, Hauptmann der Sureki",
			text = { L["Sikran, Hauptmann der Sureki"], "", L["- Kapitänsfanfare (Tankkombo): Durchbohren und Phasenvorstoß hinterlassen Debuffs -> Tankwechsel nach jeder Kombo."], L["- Dezimieren: Strahlen auf mehrere Spieler -> Linien vom Raid wegdrehen, nicht durch andere zielen."], L["- Phasenklingen: Linienangriffe auf Spieler -> ausweichen, Spuren auf dem Boden meiden."], L["- Zerschmetternder Schwung: riesiger Flächenangriff, Schaden sinkt mit Entfernung -> rechtzeitig weit weg vom Boss."], L["- Pfeilhagel: raidweiter Schaden -> Heiler-CDs."], "", L["Taktik: Boss mittig tanken, Fernkampf locker verteilt; vor jedem Schwung geschlossen auf Abstand gehen und Strahlen sauber ausrichten."] },
			wichtig = L["Wichtig: Tankwechsel nach jeder Kombo, sonst stirbt der Tank an den Debuffs. Dezimieren-Ziele drehen Strahlen weg vom Raid. Vor dem Schwung geschlossen auf Abstand. Heiler-CDs fest auf Pfeilhagel rotieren."],
			post = { L["SIKRAN: Beim Schwung weit weg! Strahlen vom Raid wegdrehen!"], L["Tankwechsel nach jeder Kombo. Phasenklingen ausweichen."] },
		},
		{ e = { 2918 }, j = 2609, en = "Rasha'nan", de = "Rasha'nan",
			text = { L["Rasha'nan"], "", L["- Rollende Säure: Säurewellen rollen durch den Raum -> rechtzeitig seitlich ausweichen bzw. durch Lücken gehen."], L["- Spinnfäden: Netzfäden binden Spieler -> weglaufen, um sie zu zerreißen, keine Fäden durch den Raid ziehen."], L["- Ätzender Sprühnebel: raidweiter Schaden + DoT -> Heiler-CDs rotieren."], L["- Befallene Brut: Spinnen-Adds -> schnell mit AoE töten."], L["- Wilder Ansturm (Tank): schwerer Treffer -> Defensiv-CDs, Tankwechsel."], "", L["Taktik: Raid zusammen halten und Wellen/Fäden geordnet abarbeiten; wenn sie die Plattform wechselt, zügig nachziehen und Pfützen an den Rand legen."] },
			wichtig = L["Wichtig: Fäden durch Weglaufen zerreißen, nie durch den Raid ziehen. Säurewellen gehen vor DPS. Heiler-CDs auf Sprühnebel rotieren. Brut sofort per AoE. Beim Plattformwechsel zügig nach, Pfützen außen."],
			post = { L["RASHA'NAN: Säurewellen ausweichen! Fäden weglaufend zerreißen!"], L["Adds mit AoE töten, Heiler-CDs bei Sprühnebel. Boss beim Plattformwechsel folgen."] },
		},
		{ e = { 2919 }, j = 2612, en = "Broodtwister Ovi'nax", de = "Brutverderber Ovi'nax",
			text = { L["Brutverderber Ovi'nax + Kolossale Spinnen, Gefräßige Würmer, Blutparasiten"], "", L["- Experimentelle Dosis: markierte Spieler müssen je ein Ei zerbrechen -> Eier geplant von innen nach außen öffnen, sonst entstehen verstärkte Adds."], L["- Blutparasiten: fixieren Spieler und vermehren sich -> zusammenziehen, mit AoE zuerst töten."], L["- Gefräßige Würmer: stationär, wirken Giftstoß -> durchgehend unterbrechen, Boss auf die Würmer stellen."], L["- Schwarzes Blut aufnehmen: Raidschaden, Pfützen, Blutüberlauf verstärkt berührte Eier/Adds -> Pfützen meiden, Heiler-CDs."], L["- Flüchtiges Gebräu (Tank): DoT, danach Raidschaden nach fehlendem Leben -> Tankwechsel, Tank voll heilen."], "", L["Taktik: Raum in drei Bereiche, Boss pro Phase in einen Bereich ziehen; Spinnen von den Tanks unter den Boss, Prio Parasiten > Würmer > Spinnen."] },
			wichtig = L["Wichtig: Kick-Rotation auf die Würmer ist Pflicht – ungekickter Giftstoß kostet den Raid. Eier nur in geplanter Reihenfolge öffnen, nie Blut an Eier bringen. Tank nach Gebräu voll heilen, dann Tankwechsel."],
			post = { L["OVI'NAX: Parasiten zuerst! Würmer durchgehend kicken!"], L["Dosis-Ziele brechen ihr Ei. Tankwechsel bei Gebräu, Tank voll heilen."] },
			marker = { name = L["Ovi'nax (Würmer)"], order = { 8, 7, 6, 5 }, note = L["Ein Symbol pro Gefräßigem Wurm, jede Kick-Gruppe unterbricht ihr Symbol."] },
		},
		{ e = { 2920 }, j = 2601, en = "Nexus-Princess Ky'veza", de = "Nexusprinzessin Ky'veza",
			text = { L["Nexusprinzessin Ky'veza"], "", L["- Leerenschredder (Tank): stapelnder Schaden + DoT -> Tankwechsel nach jeder Serie."], L["- Attentat: markierte Spieler gehen zu festen Punkten, es entstehen Netherrisse -> Tank zieht den Boss auf die Gegenseite, Raid bleibt in der Mitte."], L["- Zwielichtgemetzel: Abbilder stürmen auf Markierte zu -> an Markierungspunkte gehen, Linien der Nexusdolche ausweichen."], L["- Königsmord (Zwischenphase): Strahlen von den Seiten -> niemanden treffen, nur entlang des eigenen Strahls bewegen."], L["- Unter 10 % Leben tötet sie Spieler sofort -> Leben jederzeit hoch halten."], "", L["Taktik: Boss mittig tanken, Raumpunkte (Sechseck) als Ablageplätze festlegen, Risse durch Bossbewegung aufheben lassen; Heroisch zusätzlich Finsterniszonen verlassen."] },
			wichtig = L["Wichtig: Leben immer über 10 % halten – Defensivs und Heilung vor Spitzen. Ablagepunkte vor dem Pull fest zuteilen. Königsmord: nur entlang des eigenen Strahls. Tankwechsel nach jeder Schredder-Serie."],
			post = { L["KY'VEZA: Markierte an die Punkte! Leben über 10 % halten!"], L["Dolchlinien meiden, Strahlen der Zwischenphase niemandem zeigen. Tankwechsel nach Schreddern."] },
		},
		{ e = { 2921 }, j = 2608, en = "The Silken Court", de = "Der Seidenhof",
			text = { L["Der Seidenhof: Anub'arash und Takazj (gemeinsamer Lebenspool)"], "", L["- Bindende Netze: Fernkämpfer erzeugen Netzlinien -> damit Anub'arashs Rücksichtslosen Ansturm stoppen, Netze danach gezielt zerreißen."], L["- Stechender Schwarm: Debuff auf Spielern -> bei Takazj bannen, Stapel betäuben ihn und unterbrechen Kataklysmische Entropie."], L["- Netzbombe / Netzwirbel: Netze und Zug zur Mitte -> gegenlaufen, keine Netze durch den Raid ziehen."], L["- Giftregen und Schwarmbefehl: Flächen und Käfer-Adds -> ausweichen, Adds wegspalten."], "", L["Taktik: Beide Bosse getrennt tanken, Anub'arash zum Phasenwechsel in die Mitte holen; Bannungen an Takazj zum richtigen Zeitpunkt, Heldentum in Phase 2."], L["Mythisch: Spieler wählen zu Beginn Zeichen der Wut oder Paranoia und müssen Kugeln der eigenen Farbe aufnehmen."] },
			wichtig = L["Wichtig: Stechender Schwarm nur am Takazj und nur auf Ansage bannen, sonst fehlt die Unterbrechung von Kataklysmischer Entropie. Netzlinien gezielt vor Anub'arashs Ansturm legen. Heldentum Phase 2."],
			post = { L["SEIDENHOF: Ansturm mit Netzlinien stoppen! Schwarm bei Takazj bannen!"], L["Netzwirbel: gegenlaufen. Gemeinsamer Lebenspool, alles auf beide Bosse."] },
		},
		{ e = { 2922 }, j = 2602, en = "Queen Ansurek", de = "Königin Ansurek",
			text = { L["Königin Ansurek + Adds auf den Plattformen (Phase 2), Akolythen (Phase 3)"], "", L["- Phase 1 Tankkombo: Verflüssigen (Tank A) und Fressen (Tank B, großer Absorb) -> Tankwechsel, Tank B gezielt heilen."], L["- Reaktives Toxin / Giftnova: Spieler springen über die Schaumpfütze über die Nova -> Toxin nahe Boss ablegen, Wellen ausweichen; Seidengruft-Spieler befreien."], L["- Zwischenphase: Entreißen zieht alle zum Boss -> weit weglaufen, unter dem Boss stirbt man sofort."], L["- Phase 2: Raid steigt Plattform für Plattform auf -> Leerensprecher/Akolythen unterbrechen, Gruftwächter und Ausstoßer töten, Düsternisberührung bannen."], L["- Phase 3: Akolythen in der Mitte -> Schilde brechen und unterbrechen, vor Schäumender Völlerei tot; Portale aus Abyssischer Infusion nutzen."], "", L["Taktik: Phase 1 im Uhrzeigersinn um den Rand rotieren; Phase 2 in zwei Teams spielen; Phase 3 Tankwechsel bei Befallen/Fressen und Königliche Verdammnis vor dem Boss nehmen."] },
			wichtig = L["Wichtig: Düsternisberührung sofort bannen, Leerensprecher/Akolythen fest kicken. Fressen-Tank vorab gezielt heilen. Zwischenphase: sofort weglaufen. Phase 1 Rotation im Uhrzeigersinn einhalten."],
			post = { L["ANSUREK: Toxin am Boss! Akolythen kicken und vor Völlerei töten!"], L["Zwischenphase: weg vom Boss laufen. Phase 3: Portale nutzen, Tankwechsel beachten."] },
			marker = { name = L["Ansurek (Kicks)"], order = { 8, 7, 6 }, note = L["Totenkopf, Kreuz, Viereck auf die zu unterbrechenden Leerensprecher bzw. Akolythen, feste Kick-Gruppen."] },
		},
	},
})

Add({ key = "lou", exp = "tww", games = "retail", name = L["Befreiung von Lorenhall"], en = "Liberation of Undermine", de = "Befreiung von Lorenhall", short = "LoU",
	ids = { 2769 }, ji = 1296,
	bosses = {
		{ e = { 3009 }, j = 2639, en = "Vexie and the Geargrinders", de = "Strolch und die Gangzwinger",
			text = { L["Strolch und die Gangzwinger + Biker, Grubenmechaniker"], "", L["- Schutzpanzerung: Strolch hat Stapel Schadensreduktion -> Biker töten, ihr Motorrad übernehmen und in den Boss rammen, um Stapel zu entfernen."], L["- 100 Energie: Gnadenloses Gemetzel -> vorher alle Stapel entfernen, sonst Wipe."], L["- Öl versprühen: markierte Spieler legen Ölpfützen -> am Raumrand ablegen, nicht hineinlaufen."], L["- Tankbrecher: schwerer Physischer Treffer -> Tankwechsel nach jedem Stapel."], L["- Zwischenphase (Boxenstopp): Boss nimmt doppelten Schaden -> Grubenmechaniker unterbrechen/kontrollieren, Splitterpfützen meiden, Heiler-CDs."], "", L["Taktik: Biker schnell töten und Motorräder gezielt fahren, Öl am Rand sammeln; in der Zwischenphase alle Offensiv-CDs auf den Boss."] },
			wichtig = L["Wichtig: Motorradfahrer vorab fest einteilen. Schutzpanzerung-Stapel vor 100 Energie unbedingt auf null, sonst Wipe. Öl nur am Rand. Boxenstopp: Mechaniker kontrollieren, alle Offensiv-CDs auf den Boss."],
			post = { L["STROLCH: Biker töten, Motorräder in den Boss rammen!"], L["Öl an den Rand. Zwischenphase: Mechaniker kicken, alle CDs auf den Boss."] },
			marker = { name = L["Strolch (Mechaniker)"], order = { 8, 7, 6, 5 }, note = L["Je ein Symbol auf die Grubenmechaniker der Zwischenphase für Kicks und Betäubungen."] },
		},
		{ e = { 3010 }, j = 2640, en = "Cauldron of Carnage", de = "Kessel des Gemetzels",
			text = { L["Kessel des Gemetzels: Leuchtendo und Torq"], "", L["- Abstand: Bosse nie näher als ca. 40 Meter zueinander -> Tanks halten sie auf gegenüberliegenden Seiten."], L["- Schrottbombe (Leuchtendo): Soak mit dem ganzen Team -> nie allein; danach Feuerwellen und Lavaringen ausweichen."], L["- Statische Ladung (Torq): Bewegung füllt eine Leiste, Stillstand leert sie -> bei voller Leiste Betäubung, Bewegung dosieren."], L["- Donnertrommelsalve: Pfützen unter jedem Spieler -> zwei ablegen, dann weitergehen."], L["- Tanks: Eruptionsstampfer bzw. Blitzhieb (Physisch + Natur) -> Defensiv-CDs."], "", L["Taktik: Raid in zwei gleich starke Teams teilen, eines pro Boss; in der Zwischenphase prallen die Bosse zusammen, dann Seiten tauschen, um die Stapel zurückzusetzen."] },
			wichtig = L["Wichtig: Teams gleich stark inkl. Heilern aufteilen. Bosse nie zusammenkommen lassen außer in der Zwischenphase. Statische Ladung: nur kurze Bewegungen. Schrottbombe immer mit dem ganzen Team soaken."],
			post = { L["KESSEL: Bosse getrennt halten! Schrottbombe mit allen soaken!"], L["Torq-Seite: Bewegung dosieren. Zwischenphase: Seiten tauschen."] },
		},
		{ e = { 3011 }, j = 2641, en = "Rik Reverb", de = "Rik Resonanz",
			text = { L["Rik Resonanz + Verstärker"], "", L["- Verstärker: erscheinen paarweise (am Boss und an einem Fernkämpfer) -> durch Rechtsklick entleeren, bevor sie voll sind und Durchdrehen den Raid trifft."], L["- Schallkanone: Strahl auf einen Spieler -> vom Raid wegzielen."], L["- Fehlerhafter Stromschlag: Kettenschaden -> verteilt stehen; Resonanzechos-Wellen ausweichen."], L["- Schallwelle (Tank): frontale Auto-Attacke mit Stapeln -> Boss vom Raid wegdrehen, Tankwechsel bei ca. 4-6 Stapeln."], L["- Zwischenphase: Boss nimmt kaum Schaden -> zum markierten durchgedrehten Verstärker laufen, Welle dort nehmen, bis vier Verstärker zerstört sind."], "", L["Taktik: Boss nach jedem Verstärkerpaar umsetzen und über 15 Meter von Verstärkern fernhalten; Entleeren rotieren, Zwischenphase von Verstärker zu Verstärker springen."] },
			wichtig = L["Wichtig: Entleeren der Verstärker fest rotieren, Boss nach jedem Paar umsetzen (über 15 m Abstand). Schallkanone weg vom Raid. Tank dreht Boss weg, Tankwechsel nach Stapelansage. Zwischenphase gemeinsam laufen."],
			post = { L["RIK: Verstärker entleeren bevor sie voll sind! Schallkanone wegzielen!"], L["Boss weg von Verstärkern tanken. Zwischenphase: zum markierten Verstärker laufen."] },
		},
		{ e = { 3012 }, j = 2642, en = "Stix Bunkjunker", de = "Stix Kojenschrotter",
			text = { L["Stix Kojenschrotter + Schrottmeister, Schrottplatzhyänen"], "", L["- Rollender Müll: markierte Spieler werden zur Kugel -> Müllhaufen und Hyänen einsammeln, wachsen und dann in Bomben und den Boss rollen."], L["- Weggeworfene Doomsplosive: große Bomben -> unbedingt mit einer großen Kugel überrollen, sonst Wipe."], L["- Verbrennungsofen: verbrennt Müllhaufen, Giftdämpfe stapeln -> verteilt stehen, brennende Haufen meiden."], L["- Schrottmeister: wirkt Schrottraketen -> unterbrechen bzw. mit mittelgroßer Kugel aufnehmen."], L["- Abriss / Kernschmelze (Tank): Tankwechsel nach jedem Abriss, CDs für Kernschmelze."], "", L["Taktik: Kugeln nicht in andere Spieler rollen, Größe in Reihenfolge klein > mittel > groß aufbauen; bei Overdrive (Boss fliegt) nur überleben und Gefahren ausweichen."] },
			wichtig = L["Wichtig: Kugelrollen fest einteilen, Doomsplosive nie liegen lassen (Wipe). Kugeln nie in Spieler rollen. Schrottmeister fest kicken. Tankwechsel nach jedem Abriss, CDs für Kernschmelze."],
			post = { L["STIX: Kugeln: erst wachsen, dann in Bomben und Boss rollen!"], L["Schrottmeister kicken. Verteilt stehen bei Verbrennungsofen. Tankwechsel nach Abriss."] },
			marker = { name = L["Stix (Schrottmeister)"], order = { 8, 7 }, note = L["Totenkopf und Kreuz auf die Schrottmeister für feste Kicks."] },
		},
		{ e = { 3013 }, j = 2653, en = "Sprocketmonger Lockenstock", de = "Ritzelkrämer Lockenstock",
			text = { L["Ritzelkrämer Lockenstock + Goblinerfindungen (Geschütze)"], "", L["- Fußsprenger: Minen am Boden -> nach Absprache gezielt auslösen bzw. räumen, nicht wahllos hineinlaufen."], L["- Vermurkst: Bohrer auf Spielern -> am Rand ablegen, vom Raid weg."], L["- Erfindungen aktivieren: Strahlen, Raketen und Magneten der Geschütze -> ausweichen, Förderbänder beachten."], L["- Kabelübertragung: Linien durch den Raum -> Boss in sichere Bereiche ziehen, Linien meiden."], L["- Tank: Gravi-Schleim-Stapel -> Tankwechsel; Pyro-Partypaket -> Bombe weit weg vom Raid tragen."], "", L["Taktik: Boss mittig tanken, Mechaniken am Rand ablegen und Geschützsalven ausweichen; Phase 2 (Forschung und Zerstörung) mit Heiler-CDs gegen Schallknall-Raidschaden."] },
			wichtig = L["Wichtig: Minen nur nach Absprache auslösen. Pyro-Partypaket-Träger weit weg vom Raid. Bohrer am Rand ablegen. Tankwechsel bei Schleim-Stapeln. Heiler-CDs für den Schallknall in Phase 2 aufsparen."],
			post = { L["LOCKENSTOCK: Geschützen ausweichen! Bohrer und Bomben weg vom Raid!"], L["Minen nur nach Absprache auslösen. Tankwechsel bei Gravi-Schleim."] },
		},
		{ e = { 3014 }, j = 2644, en = "The One-Armed Bandit", de = "Der Einarmige Bandit",
			text = { L["Der Einarmige Bandit + Walzenassistenten"], "", L["- Gewinnlinie: Münzen fliegen durch den Raum -> neben der Münze stehen für Buff, nicht treffen lassen; Münze an der Wand erneut wegkicken."], L["- Walzenassistenten (100 Energie): drei Adds mit Münzen -> Überladung unterbrechen, Adds töten."], L["- Münzen einwerfen: zwei Münzen am Boss per Extra-Button einwerfen -> jede Kombination nur einmal und rechtzeitig, sonst Wipe."], L["- Großer Treffer (Tank): wegtragen, Schockfeld an den Rand legen; Faulige Abgase: Heilabsorb -> Burst-Heilung."], L["- Phase 2 (Das Spiel ist manipuliert): feste Abfolge mit Strahlen und steigendem Schaden -> Strahlen ausweichen, dann burnen."], "", L["Taktik: Kombinationen vorher festlegen und ansagen, Münzträger fest einteilen; Adds schnell töten, Phase 2 mit Heldentum vor dem Explosiven Jackpot beenden."] },
			wichtig = L["Wichtig: Münzträger fest einteilen, jede Kombination nur einmal – Fehler bedeutet Wipe. Überladung der Walzenassistenten kicken. Heilabsorbs der Abgase gezielt wegheilen. Heldentum für Phase 2."],
			post = { L["BANDIT: Überladung kicken! Jede Münzkombi nur einmal!"], L["Münzen sofort einwerfen. Tank: Schockfelder an den Rand. Phase 2 burnen."] },
			marker = { name = L["Einarmiger Bandit"], order = { 8, 7, 6 }, note = L["Totenkopf, Kreuz, Viereck auf die drei Walzenassistenten für Kicks und Münzträger."] },
		},
		{ e = { 3015 }, j = 2645, en = "Mug'Zee, Heads of Security", de = "Mug'Zee, Wachleitung",
			text = { L["Mug'Zee, Wachleitung: Mug (rechts) und Zee (links)"], "", L["- Seitenwahl: die Seite mit den meisten Spielern bestimmt, wer aktiv ist; Energie bei 100 = Wipe -> Seiten regelmäßig wechseln."], L["- Erdbeben-Kerker (Mug): Kreise auf zwei Spielern -> nebeneinander, nicht überlappend, Adds unterbrechen und töten."], L["- Goldene Schlagringe (Mug, Tank): Tankwechsel, Goldtropfen-Stapel rechtzeitig in Pfützen abbauen; Finger-Kanone frontal meiden."], L["- Instabile Krabbelminen (Zee): fixieren Spieler -> vom Off-Tank einzeln auslösen, keine Kettenreaktion."], L["- Goblingelenkte Rakete und Doppelschuss (Zee): Rakete mit Gruppe soaken, Doppelschuss nimmt der Tank, Ziel läuft weg von Minen."], "", L["Taktik: Raid in Gruppen für Kerker und Soaks teilen, etwa zwei Mug- auf einen Zee-Zyklus; bei 40 % Zwischenphase mit dem Boss mitlaufen, um Kugelhagel auszuweichen."] },
			wichtig = L["Wichtig: Seitenwechsel konsequent nach Ansage, 100 Energie bedeutet Wipe. Minen nur vom Off-Tank einzeln auslösen. Goldtropfen-Stapel rechtzeitig in Pfützen abbauen. Kerker-Kreise nie überlappen."],
			post = { L["MUG'ZEE: Seiten wechseln vor 100 Energie! Raketen gemeinsam soaken!"], L["Minen einzeln auslösen. Kerker nicht überlappen. Tank: Goldstapel abbauen."] },
		},
		{ e = { 3016 }, j = 2646, en = "Chrome King Gallywix", de = "Chromkönig Gallywix",
			text = { L["Chromkönig Gallywix + Dunkelzünder-Techniker und -Schraubenschlüssler"], "", L["- Streukanister (Tank): Frontal mit Heilabsorb -> Tankwechsel; Tank immer in Nahkampfreichweite halten, sonst Gatlingkanone."], L["- Gezündete Kanister: Gruppensoaks -> mit festen Gruppen teilen."], L["- Große böse Bombenladung: Bomben landen im Raum -> gezielt in die Gigaspulen bringen bzw. auslösen, um diese abzuschalten."], L["- Gigaspulen / Gigaschuss: Strahlen und Linien -> ausweichen, Bombentechnik der Spulen nutzen."], L["- Ego-Check und Raidtreffer: Heiler-CDs; Techniker-Adds schnell töten."], "", L["Taktik: Phase 1 Bomben und Spulen kontrolliert abarbeiten, Adds priorisieren; Zwischenphase Panzerung brechen, Phase 3 mit Heldentum vor der totalen Zerstörung burnen."] },
			wichtig = L["Wichtig: Tank nie aus Nahkampfreichweite, sonst Gatlingkanone auf den Raid. Bomben gezielt in die Spulen, nicht wahllos. Feste Soak-Gruppen für Kanister. Techniker-Adds priorisieren, Heldentum für Phase 3."],
			post = { L["GALLYWIX: Kanister gemeinsam soaken! Bomben in die Spulen!"], L["Tank in Nahkampf halten, Tankwechsel nach Streukanister. Adds zuerst."] },
		},
	},
})

