			wichtig = L["Wichtig: Magier-Kicks fest per Symbol, Magier vor Assassinen töten. Boss zuerst zu den Zielkammern ziehen. Tankwechsel nach jeder Peitsche. Bei Ausstoßung nie am Rand. Kugel-Träger raus aus dem Raid."],
			post = { L["NAAZINDHRI: Kammern mit Strahlen zerstören! Magier kicken!"], L["Weg vom Rand bei Rückstoß. Markierte Kugeln weg vom Raid. Tankwechsel bei Peitsche."] },
			marker = { name = L["Naazindhri"], order = { 8, 7, 6 }, note = L["Totenkopf, Kreuz, Viereck auf die Schattenwachen-Magier für feste Kick-Gruppen."] },
