			wichtig = L["Wichtig: Auslöschung mit genug Soakern, Immunitäten gezielt einsetzen. Sammler in der Zwischenphase synchron töten, Gruppen vorher fest. Stillkreise meiden (Heiler!). Letzte Phase: Heldentum, gegen das Loch laufen."],
			post = { L["ARAZ: Auslöschung zu zehnt soaken! Sammler gleichzeitig töten!"], L["Stillkreise meiden. Letzte Phase: weg vom schwarzen Loch, Boss brennen."] },
			marker = { name = L["Araz (Sammler)"], order = { 8, 7, 6 }, note = L["Je ein Symbol auf die drei Arkanen Sammler in der Zwischenphase, jede Gruppe nimmt ihr Symbol."] },
