			wichtig = L["Wichtig: Alle drei gleichmäßig runter. Seelenfragmente sofort soaken, sonst Seelenbombe-Wipe. Leerenzonen nur von den eingeteilten Fernkämpfern nehmen. Debuff bannen. Tankwechsel nach Augenstrahl."],
			post = { L["SEELENJÄGER: Alle drei gleichmäßig runter! Seelenfragmente soaken!"], L["Jagd teilen, Linien ausweichen. Zwischenphase: Adarus/Velaryn verteilen, Ilyssa stacken."] },
		},
		{ e = { 3133 }, j = 2747, en = "Fractillus", de = "Fraktillus",
			text = { L["Fraktillus"], "", L["- Kristalline Schockwelle: markierte Spieler erzeugen Kristallwände in ihrer Bahn -> Wände gleichmäßig auf die Bahnen verteilen."], L["- Erreicht eine Bahn sechs Wände: Boss erhält starken Schadensbuff -> praktisch Wipe, jede Bahn im Blick behalten."], L["- Splitterhülle: betroffene Spieler werden zurückgeschleudert und brechen Wände -> nur so viele Wände brechen wie nötig, Bahnen vorher absprechen."], L["- Nullverzehr: Debuff mit Flächenschaden -> sofort vom Raid weglaufen."], L["- Tanktreffer: schwerer Schlag -> Defensiv-CDs und Tankwechsel."], "", L["Taktik: Raid Bahnen fest zuteilen, Wände und Wandbrecher per Ansage steuern, damit keine Bahn volläuft und kein Spieler zum Boss geschleudert wird."] },
			wichtig = L["Wichtig: Wandzählung pro Bahn laut ansagen, keine Bahn erreicht 6 Wände. Splitterhülle-Ziele brechen nur abgesprochene Wände. Nullverzehr sofort raus. Defensiv auf Tanktreffer, Tankwechsel danach."],
			post = { L["FRAKTILLUS: Keine Bahn auf 6 Wände! Wände gezielt brechen!"], L["Nullverzehr raus aus dem Raid. Bahnen-Zuteilung einhalten."] },
		},
		{ e = { 3134 }, j = 2690, en = "Nexus-King Salhadaar", de = "Nexuskönig Salhadaar",
			text = { L["Nexuskönig Salhadaar + Königliche Leerenschwinge, Zwischenphasen-Adds"], "", L["- Erlass: Eidgebunden: drei Stapel -> durch den Erobern-Soak am Tank abbauen, sonst Gedankenkontrolle am Phasenende."], L["- Belagern / Enthaupten: Linien ausweichen, Enthaupten-Ziele laufen vom Raid weg; Fraktalklaue zieht zum Rand -> Mitte halten."], L["- Phase 2: Netherbrecher-Portale kopieren den Dimensionsatem -> Portale gesammelt an einen Rand legen, Atem vom Raid wegdrehen, Drache fokussieren."], L["- Zwischenphasen: Raid teilt sich auf zwei Plattformen (Titan vor 100 Energie töten, Nexusprinz unterbrechen); danach Drache töten, bevor Königshunger endet."], L["- Phase 3: Galaktischer Schlag erzeugt Dunkle Sterne -> mit Sternentöter-Schwung die Sterne zerstören, Ringen ausweichen, Tankwechsel nach jedem Treffer."], "", L["Taktik: Phase 1 sauber Stapel abbauen und Tankkombo rotieren; in Phase 2 Drache priorisieren, Zwischenphasen geteilt spielen, Phase 3 vor dem Enrage burnen."] },
			wichtig = L["Wichtig: Eid-Stapel rechtzeitig über den Erobern-Soak abbauen, sonst Gedankenkontrolle. Portale an einem Rand sammeln. Drache vor Ende von Königshunger töten. Zwischenphasen-Teams vorab festlegen."],
			post = { L["SALHADAAR: Eid-Stapel am Tank abbauen! Portale an einen Rand!"], L["Drache priorisieren. Phase 3: Sterne mit dem Schwung zerstören, Ringe ausweichen."] },
		},
		{ e = { 3135 }, j = 2691, en = "Dimensius, the All-Devouring", de = "Dimensius der alles Verschlingende",
			text = { L["Dimensius der alles Verschlingende + Lebende Masse, Artoshion, Pargoth"], "", L["- Lebende Masse: Adds lassen Kugeln (Überschüssige Masse) fallen -> schnell töten, Kugeln gezielt von zugeteilten Spielern aufnehmen."], L["- Umgekehrte Schwerkraft: Spieler werden angehoben -> Träger der Überschüssigen Masse befreien sie durch Soaken."], L["- Zerschmetterter Raum / Verschlingen: Kreis von allen außer Tanks soaken; Verschlingen zieht den Raid an -> gegenlaufen, Heiler-CDs."], L["- Phase 2 (Plattformen): Artoshion und Pargoth mit Leerenwächter-Adds -> Masseauswurf-Linien in eine Ecke legen, Schwerkraftkreise korrekt kombinieren."], L["- Phase 3: Sterne und Wellen, Ereignishorizont -> beim Verschlingen rechtzeitig in den Stern, Wellen nach Ansage nehmen oder auslassen."], "", L["Taktik: Phase 1 Adds und Kugeln zuteilen, Zwischenphasen fliegend Hindernissen ausweichen; nie in den Körper von Dimensius fliegen. Heldentum in Phase 3."] },
			wichtig = L["Wichtig: Kugeln nur von fest zugeteilten Spielern aufnehmen. Hochgehobene Spieler sofort befreien. Zerschmetterter Raum: alle außer Tanks rein. Nie in den Boss fliegen. Heldentum für Phase 3 aufsparen."],
			post = { L["DIMENSIUS: Massen-Adds töten, Kugeln nach Zuteilung aufnehmen!"], L["Hochgehobene Spieler befreien. Nicht in den Boss fliegen! Heldentum in Phase 3."] },
		},
	},
})

