			post = { L["VORASIUS: Kriecher an die Wände kiten und dort töten! Leerenatem: auf die offene Seite!"], L["Tank-Soak, Wechsel nach 2 Schlägen. Bei Brüllen gegenlaufen, Tank bleibt immer am Boss."] },
