			wichtig = L["Wichtig: Kugel-DDs fest einteilen, keine Kugel darf den Boss erreichen (Wipe). Klone sofort kicken/kontrollieren. Befehl-Ziele raus an den Rand. Vor 100 Energie Boss an den Rand, Burst während der Auflösung."],
			post = { L["SALHADAAR: Kugeln dürfen den Boss nie erreichen! Klone sofort kicken!"], L["Pfützen am Rand ablegen, Boss vor 100 Energie an den Rand ziehen. Stacheln ausweichen."] },
			marker = { name = L["Salhadaar (Klone)"], order = { 8, 7, 6 }, note = L["Gebrochene Projektionen markieren, jede Kick-Gruppe unterbricht ihr Symbol."] },
