			wichtig = L["Wichtig: Drachen über 15 m getrennt, Leben max. 10 % auseinander. Furcht sofort bannen. Düsternis-Soaker rotieren (Debuff). Leerenkugeln kicken/kontrollieren. Mitternachtsflammen in der Barriere. Nie hinter die Drachen."],
			post = { L["VAELGOR & EZZORAK: Leben gleich halten, Drachen über 15 m getrennt! Düsternis soaken!"], L["Leerenkugeln kicken/CC. Flammen: in die Barriere, Ungebundenen Schatten sofort töten."] },
