			wichtig = L["Wichtig: Gottesschild sofort per Massenbannung (Priester) entfernen. Alle drei gleichmäßig runter, gleichzeitig töten. Bei Auren raus aus der Reichweite. Je Todesurteil-Kreis genau eine Gruppe. Tankwechsel nach Richturteil-Stufe."],
			post = { L["LICHTBLINDE VORHUT: Alle 3 gleichzeitig töten! Auren bei 100 Energie meiden!"], L["Gottesschild massenbannen, Todesurteil soaken, Schild des Rächers verteilt + bannen."] },
			marker = { name = L["Lichtblinde Vorhut"], order = { 8, 7, 6 }, note = L["Ein Symbol pro Paladin (Lichtblut, Bellamy, Senn) für Tank- und Schadenszuweisung."] },
