			post = { L["DER GEWUNDENE ALTAR: Guillotine mit 5+ soaken, dann raus! Kontrollierte vor dem Rand retten!"], L["Kugeln/Geister per Tank-Frontal zerstören. Nachteinbruch-Schild sofort brechen. P3 beide zusammen töten."] },
