-- Molten Core: wichtige Details zu den vorhandenen Taktiken
do
	local W = {
		[663] = L["Wichtig: Fluch des Lucifron trifft alle (Mana, Wut, Energie) – zuerst Tanks entfluchen, dann Heiler, dann den Rest; Magier/Druiden entfluchen vor Schaden. Drohende Verdammnis bei allen sofort bannen (Priester, Paladine)."],
		[664] = L["Wichtig: Feste Jäger-Reihenfolge für Einlullender Schuss mit Ersatzjäger, falls einer verfehlt. Furchtschutz zuerst auf den Haupttank, Krieger halten Berserkerwut für Panik bereit. Niemand außer dem Tank vor Magmadar."],
		[665] = L["Wichtig: Fluch des Gehennas zuerst von Tanks entfernen, dann von Heilern, dann vom Rest – Magier/Druiden fest einteilen. Adds getrennt tanken und zuerst töten. Unentfluchte Tanks sind die häufigste Wipe-Ursache."],
		[666] = L["Wichtig: Jeder Hexer verbannt nur sein Symbol und erneuert rechtzeitig. Feuerschwörer einzeln töten, Nahkampf vor dem Tod raus (Eruption). Garr weg vom Raid tanken (Antimagischer Impuls entfernt Buffs)."],
		[667] = L["Wichtig: Fluch des Shazzrah sofort entfernen (Magier/Druiden), Magiedämpfung vom Boss bannen (Priester) bzw. läutern (Schamanen). Nach Blinzeln spottet der nächste Tank; Heiler und Zauberer bleiben auf Distanz (Gegenzauber)."],
		[668] = L["Wichtig: Bombenträger läuft sofort zum festen Platz außerhalb, Heiler halten ihn hoch. Mana entzünden zuerst bei Heilern bannen (Priester, Paladine). Bei Inferno Nahkampf raus. Bombe im Raid = typischer Wipe."],
		[669] = L["Wichtig: Pro Priester feste Unterbrecher-Reihenfolge (Schurken Tritt, Krieger Schildhieb/Zuschlagen, Magier Gegenzauber). Schattenwort: Schmerz zuerst von Tanks bannen. Sulfuron nicht vor den Priestern töten."],
		[670] = L["Wichtig: Kernwüter niemals angreifen, Fernkampf und Flächenschaden nur auf Golemagg. Tankwechsel nach festem Magmaspritzer-Stapel. Gegen Ende (Erdbeben) Nahkampf raus, Fernkampf beendet den Kampf."],
		[671] = L["Wichtig: Bei Magiereflexion stoppen Zauberer, bei Schadensschild Nahkampf und Jäger. Heiler der Adds zuerst und konsequent unterbrechen. Majordomus nicht angreifen – nur Adds zählen. In die Grube Teleportierte laufen zurück."],
		[672] = L["Wichtig: Zweittank immer hoch in der Bedrohung, falls der Haupttank zurückgestoßen wird. Feuerwiderstand und Große Feuerschutztränke für Tanks/Nahkampf. Bei Abtauchen alle auf die Söhne der Flamme – Heiler mit Mana haushalten."],
	}
	local mc = RM.Data.RaidByKey("mc")
	for _, b in ipairs(mc and mc.bosses or {}) do b.wichtig = W[b.e[1]] end
end

RM.Data.Build()
